const prompts = [
  {id:1,title:"Aged Concrete — Surface Texture",category:"materials",desc:"A high-fidelity aged concrete surface with fine pores, subtle mineral variation, realistic weathering and natural tonal depth.",prompt:"Aged concrete surface texture, fine irregular pores, subtle mineral deposits, realistic weathering, nuanced cool grey tonal variation, soft directional studio lighting, physically accurate roughness and micro-detail, seamless material study, neutral background, ultra-detailed, photorealistic.",negative:"Plastic appearance, repeating patterns, excessive cracks, artificial gloss, low resolution, text, watermark.",kind:"material",bg:"#45494b",art:"linear-gradient(135deg,#aaa,#494e52,#d1d0c8)",glow:"#747b7c",model:["Midjourney","DALL·E","Stable Diffusion","Flux"],tags:["Texture","Photorealistic","Surface study"]},
  {id:2,title:"Brushed Aluminium — Product Surface",category:"materials",desc:"A precision brushed aluminium surface with fine linear grain, realistic metal sheen and controlled directional reflections.",prompt:"Brushed aluminium surface, fine linear grain texture, realistic satin metal sheen, soft directional studio lighting, controlled subtle reflections, physically accurate metallic response, detailed industrial product photography, clean minimal composition, 8K material detail.",negative:"Chrome mirror finish, plastic texture, scratches, fingerprints, blown highlights, warped reflections, text, watermark.",kind:"material",bg:"#747a7d",art:"repeating-linear-gradient(120deg,#d5d8d8 0 2px,#777f84 3px 4px,#b1b5b6 5px 7px)",glow:"#9faab2",model:["Midjourney","DALL·E","Stable Diffusion","Flux"],tags:["Metal","Product surface","Studio"]},
  {id:3,title:"Carbon Fibre — Technical Material",category:"materials",desc:"A detailed woven carbon-fibre composite with tight twill structure, directional highlights and convincing technical material depth.",prompt:"Premium carbon fibre composite material, precise 2x2 twill weave, tight interlaced filaments, subtle anisotropic reflections, deep graphite and black values, controlled strip lighting revealing the weave, macro material photography, physically based shading, crisp micro-detail.",negative:"Flat printed pattern, oversized weave, plastic gloss, melted fibres, moiré, uneven grid, dust, text, watermark.",kind:"material",bg:"#15191d",art:"repeating-linear-gradient(45deg,#999 0 2px,#171a1e 2px 6px,#51575c 6px 8px)",glow:"#59636e",model:["Midjourney","Stable Diffusion","Flux"],tags:["Composite","Macro","Technical"]},
  {id:4,title:"Chromatic Aberration — Optical Effect",category:"filter-effects",desc:"A controlled chromatic aberration effect with colour-channel separation, edge fringing and a cinematic digital aesthetic.",prompt:"Chromatic aberration effect, RGB channel separation, subtle colour fringing around high-contrast edges, refined optical distortion, controlled spectral displacement, luminous blue violet and orange highlights, cinematic lighting, clean composition, intentional restrained effect, 8K detail.",negative:"Unreadable image, excessive glitch blocks, muddy colour, random noise, heavy blur, unwanted text, watermark.",kind:"effect",bg:"#071748",art:"linear-gradient(130deg,#0c44b7,#8e2dd3 38%,#ff6c19 57%,#24c6f4 76%,#15133f)",glow:"#5e39ff",model:["Midjourney","DALL·E","Stable Diffusion","Flux"],tags:["Visual effects","Chromatic","Digital"]},
  {id:5,title:"Film Grain — Analogue Texture",category:"filter-effects",desc:"Fine analogue film grain with organic luminance variation, restrained texture and a tactile photographic finish.",prompt:"Fine 35mm analogue film grain, organic luminance noise, subtle silver-halide texture, gentle tonal irregularity, rich black levels, restrained highlight bloom, natural photographic contrast, authentic scanned-film character, grain structure consistent across the frame.",negative:"Digital compression artefacts, chroma noise, posterisation, excessive grain clumps, sharpening halos, text, watermark.",kind:"effect",bg:"#292b2b",art:"radial-gradient(#a5a5a0 0.7px,transparent 1px)",glow:"#71716c",model:["Midjourney","DALL·E","Flux"],tags:["Analogue","Texture","Photography"]},
  {id:6,title:"Hoodie Mockup — Studio Apparel",category:"mockups",desc:"A premium studio apparel mockup with natural garment construction, realistic drape, precise stitching and soft directional light.",prompt:"Premium heavyweight blank hoodie studio product mockup, front-facing centred garment, natural cotton fleece texture, realistic hood volume and drawstrings, accurate ribbed cuffs and hem, subtle fabric folds, precise seams and stitching, soft neutral studio lighting, seamless charcoal background, high-end e-commerce product photography.",negative:"Human model, mannequin visible, logos, graphics, text, distorted sleeves, asymmetrical garment, floating fabric, excessive wrinkles, watermark.",kind:"fabric",bg:"#333a40",art:"linear-gradient(135deg,#aeb2b4,#4e565e 55%,#1a1e23)",glow:"#a7adb1",model:["Midjourney","DALL·E","Flux"],tags:["Apparel","Product mockup","Studio"]},
  {id:7,title:"Packaging Mockup — Product Box",category:"mockups",desc:"A clean premium packaging mockup built around accurate structure, considered lighting, precise edges and print-ready surface detail.",prompt:"Premium rigid paperboard product packaging box mockup, three-quarter perspective, realistic board thickness and folded edges, refined matte uncoated paper surface, subtle natural contact shadows, controlled studio softbox reflections, minimal neutral set, accurate proportions, high-end commercial product photography.",negative:"Bent geometry, incorrect perspective, floating box, illegible text, random logos, glossy plastic, soft edges, watermark.",kind:"mockup",bg:"#242a30",art:"linear-gradient(135deg,#d2d0c7 0 35%,#7a8186 36% 55%,#ff6b16 56% 61%,#222a32 62%)",glow:"#aab5bd",model:["Midjourney","DALL·E","Stable Diffusion","Flux"],tags:["Packaging","Product","Commercial"]},
  {id:8,title:"Glass Refraction — Light Distortion",category:"filter-effects",desc:"Prismatic light refracting through precision glass with crisp caustics, spectral dispersion and controlled reflections.",prompt:"Optical glass refraction study, precision-cut transparent glass planes, physically accurate Fresnel reflections, vivid spectral dispersion, crisp caustic light patterns, subtle cyan blue violet and amber highlights, deep black studio environment, high contrast controlled lighting, macro luxury product photography.",negative:"Cloudy opaque glass, melted forms, random rainbow noise, excessive bloom, flat lighting, dirty surfaces, text, watermark.",kind:"glass",bg:"#0c1c36",art:"linear-gradient(125deg,transparent 10%,#e7fcff 12%,#298bdb 16%,transparent 20%,#ff8a28 36%,transparent 42%,#b8a1ff 59%,transparent 65%)",glow:"#3e96ef",model:["Midjourney","DALL·E","Flux"],tags:["Optics","Refraction","Prismatic"]},
{"id":9,"title":"Blackened Steel — Oxidised Industrial Plate","category":"materials","desc":"Heat-darkened steel with layered oxide colour, restrained satin reflections and subtle manufacturing marks.","prompt":"Create a photorealistic macro material study of blackened carbon steel. Show a deep charcoal oxide layer with restrained blue-brown tempering variation, fine directional brushing, tiny edge abrasions and sparse handling marks. The surface is predominantly low-sheen satin, with narrow softbox reflections that reveal the metal without turning it into mirror chrome. Use physically plausible metalness, varied micro-roughness and crisp grazing light. Frame as a flat, evenly exposed material sample with no perspective distortion, no objects and no text.","negative":"Chrome mirror finish, painted plastic, uniform flat black, heavy rust, exaggerated scratches, fingerprints, greasy smears, melted geometry, repeating noise, text, watermark.","kind":"material","bg":"#20252a","art":"linear-gradient(120deg,#111820,#59616a,#211a19)","glow":"#687783","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Ferrous metal","Oxidation","Industrial"]},
{"id":10,"title":"Liquid Chrome — Reflective Fluid Metal","category":"materials","desc":"Highly reflective mercury-like metal with fluid folds, coherent environment reflections and polished surface tension.","prompt":"A sculptural pool of liquid chrome frozen into elegant fluid folds, photographed as a premium material study. The surface is fully metallic and mirror-polished, reflecting a controlled studio environment as long, continuous white softbox bands and dark negative shapes. Form smooth rounded ridges, thin flowing membranes and believable surface tension; avoid droplets that resemble water. Use high-contrast reflection design, clean specular continuity, accurate Fresnel behaviour and crisp silhouette separation against a deep neutral studio background. Macro product-photography realism.","negative":"Water, liquid silver paint, glitter, granular texture, broken reflections, random chrome fragments, excessive bloom, grey plastic, bubbles, text, watermark.","kind":"material","bg":"#171b20","art":"linear-gradient(145deg,#f0f2f1,#444c54 25%,#dce1e1 43%,#242a30 62%,#aab0b3)","glow":"#b7c3ce","model":["Midjourney","DALL·E","Flux"],"tags":["Liquid metal","Specular","Sculptural"]},
{"id":11,"title":"Anodised Aluminium — Interference Colour","category":"materials","desc":"Precision anodised aluminium with controlled satin grain and saturated but believable oxide-film colour.","prompt":"A precision anodised aluminium material sample in saturated electric blue with subtle violet shift at grazing angles. Preserve fine bead-blasted microtexture beneath a uniform anodic finish; the colour belongs to the oxide surface, not a layer of glossy paint. Use restrained anisotropic highlights, accurate metallic response, soft strip-light reflections and a neutral dark studio surround. Show a clean machined edge and one gently curved plane so the finish reads across changing angles. High-end industrial design photography, sharp micro-detail.","negative":"Plastic coating, automotive candy paint, rainbow oil slick, coarse glitter, mirror chrome, uneven dye, corrosion, fingerprints, text, watermark.","kind":"material","bg":"#081b40","art":"linear-gradient(115deg,#1a46b8,#13214e 35%,#8d6ee0 53%,#0c2445)","glow":"#286eea","model":["Midjourney","Flux","Stable Diffusion"],"tags":["Anodising","Metal finish","Colour shift"]},
{"id":12,"title":"Translucent Resin — Cast Pigment Depth","category":"materials","desc":"Cast resin with internal pigment suspension, edge transmission, subtle depth and polished moulded surfaces.","prompt":"Photorealistic cast translucent resin material specimen, a thick softly rounded slab containing suspended pigment clouds and fine internal colour gradients. Light must travel through the body, creating brighter transmitted edges, gentle internal scattering and subtle depth parallax. The outer surface is polished but not glass-like; show faint mould-flow traces and tiny controlled imperfections. Illuminate from behind and through one side with a large diffused source, retaining readable edge highlights and a dark neutral background. Physically plausible transmission, absorption and refraction; premium macro studio study.","negative":"Opaque plastic, liquid water, glass shards, excessive bubbles, glitter, cloudy dirt, blown-out edges, flat printed gradient, text, watermark.","kind":"material","bg":"#14233b","art":"linear-gradient(130deg,#e4a5c5,#6e6fe0 35%,#38c5c6 65%,#15253e)","glow":"#8f83e9","model":["Midjourney","DALL·E","Flux"],"tags":["Resin","Transmission","Pigment"]},
{"id":13,"title":"Frosted Glass — Satin Diffusion","category":"materials","desc":"Etched translucent glass with soft transmission, muted silhouettes and crisp polished boundaries.","prompt":"A premium frosted glass material sample with a finely etched satin surface and polished perimeter edges. The body transmits light diffusely rather than forming a clear image; objects behind it should become soft tonal silhouettes with no sharp detail. Use broad backlighting to reveal even diffusion, plus a narrow edge light for thickness and realistic Fresnel reflections. Maintain subtle surface grain, clean planar geometry and accurate glass thickness. Neutral cool studio palette, controlled highlights, no decorative styling, photorealistic material catalogue image.","negative":"Opaque white acrylic, perfectly clear glass, dirty fingerprints, scratches, rainbow dispersion, excessive haze, melted edges, mirror finish, text, watermark.","kind":"glass","bg":"#1c2b36","art":"linear-gradient(110deg,#d9e6e8,#7d9ba4 40%,#263a46 70%,#d5e3e5)","glow":"#9bbbc9","model":["Midjourney","DALL·E","Flux"],"tags":["Glass","Diffusion","Translucency"]},
{"id":14,"title":"Smoked Glass — Tinted Optical Surface","category":"materials","desc":"Dark tinted architectural glass with layered reflections, partial transmission and polished edge thickness.","prompt":"Photorealistic smoked architectural glass sample, deep neutral graphite tint with a polished flat face and visibly thick cut edge. Balance surface reflections against partial transmission: the studio softboxes should read clearly on the face while faint shapes behind the pane remain visible through the material. Use accurate Fresnel reflections, subtle absorption through thickness and clean straight edges. Compose as a three-quarter macro study with controlled black flags, cool grey highlights and no coloured cast. High-end architectural materials photography.","negative":"Opaque black acrylic, transparent window with no tint, mirror-only surface, dirty glass, severe distortion, rainbow colour, chipped edges, text, watermark.","kind":"glass","bg":"#101820","art":"linear-gradient(125deg,#6b7c87,#111820 38%,#465864 54%,#090d12)","glow":"#8ba6b8","model":["Midjourney","DALL·E","Flux"],"tags":["Tinted glass","Fresnel","Architecture"]},
{"id":15,"title":"Brushed Copper — Directional Anisotropy","category":"materials","desc":"Warm copper with fine linear brushing, elongated highlights and natural tonal oxidation at the edges.","prompt":"A precision brushed copper surface, photographed in macro. Fine parallel hairline grain runs in one consistent direction, producing elongated anisotropic highlights that follow the brushing rather than broad isotropic glare. Copper base colour remains warm and believable, with restrained tonal variation and a few subtle darker edge zones. Use a long strip softbox aligned obliquely to the grain, dark negative fill and a neutral studio environment. Physically based metallic response, controlled roughness, no decorative patina overload.","negative":"Rose-gold jewellery gloss, orange plastic, mirror chrome, random circular scratches, green verdigris covering the surface, fingerprints, harsh clipped reflections, text, watermark.","kind":"material","bg":"#39251d","art":"repeating-linear-gradient(105deg,#d58b5a 0 2px,#804a2e 3px 5px,#c17a4e 6px 8px)","glow":"#c77e53","model":["Midjourney","Flux","Stable Diffusion"],"tags":["Copper","Anisotropy","Brushed finish"]},
{"id":16,"title":"Carbonised Timber — Charred Grain","category":"materials","desc":"Deeply charred timber with raised grain, brittle carbon texture and selective warm exposed fibres.","prompt":"Macro material photograph of carbonised timber using a controlled yakisugi-inspired charred finish. Show deep blackened ridges, cracked but structurally coherent carbon layers, visible linear wood grain and occasional warm brown fibres beneath the char. Grazing side light should reveal relief without making the surface glossy. Keep the char dry, matte and tactile, with realistic irregularity and no repeated procedural pattern. Neutral dark studio background, high-resolution surface detail and natural material scale.","negative":"Wet glossy wood, uniform black paint, coal chunks, excessive deep splitting, burnt flames, artificial embossed pattern, plastic texture, text, watermark.","kind":"material","bg":"#1a1715","art":"repeating-linear-gradient(100deg,#080909 0 4px,#4d3426 5px 7px,#171312 8px 12px)","glow":"#6c4932","model":["Midjourney","DALL·E","Flux"],"tags":["Timber","Charring","Organic grain"]},
{"id":17,"title":"Technical Nylon — Woven Ripstop","category":"materials","desc":"Lightweight ripstop textile with visible reinforcement grid, fine yarn texture and controlled synthetic sheen.","prompt":"A macro studio photograph of technical ripstop nylon fabric, tightly woven with a clearly legible but fine reinforcement grid at regular intervals. Show individual yarn filaments, slight tension variation and a light crinkled hand without exaggerated folds. The finish is semi-matte with broad soft highlights, not glossy plastic. Use raking light to reveal weave relief and a neutral colour field. Maintain realistic textile scale, coherent warp and weft, accurate fibre intersections and premium outdoor-equipment material fidelity.","negative":"Printed grid, coarse basket weave, vinyl sheet, satin silk, melted fibres, random holes, oversized checks, plastic shine, text, watermark.","kind":"fabric","bg":"#26323b","art":"repeating-linear-gradient(0deg,transparent 0 7px,#89949b 8px 9px),repeating-linear-gradient(90deg,#202c35 0 7px,#687681 8px 9px)","glow":"#6e8796","model":["Midjourney","Flux","Stable Diffusion"],"tags":["Textile","Ripstop","Technical fabric"]},
{"id":18,"title":"Heavyweight Cotton Fleece — Loopback Knit","category":"materials","desc":"Dense cotton fleece with visible loopback structure, soft fibre bloom and weighty folds.","prompt":"Extreme close-up material study of heavyweight cotton loopback fleece in a neutral charcoal tone. Show dense knitted face yarns, tiny fibre halos, subtle lint and the reverse loop structure visible along a folded cut edge. Fabric should feel substantial and dry, with soft compression creases and weight-driven folds rather than silky drape. Large diffused studio source reveals the knit without flattening it; retain accurate stitch scale, natural irregularity and colour fidelity. Premium apparel textile photography.","negative":"Polar fleece pile, terry towel loops, thin jersey, synthetic shine, felt, excessive pilling, repeated knit pattern, floating cloth, text, watermark.","kind":"fabric","bg":"#24282d","art":"repeating-linear-gradient(135deg,#737a80 0 2px,#30363d 3px 5px,#555e65 6px 8px)","glow":"#69737c","model":["Midjourney","DALL·E","Flux"],"tags":["Cotton","Knit","Apparel textile"]},
{"id":19,"title":"Halation — Analogue Highlight Bleed","category":"filter-effects","desc":"Soft red-orange highlight migration around bright sources with restrained filmic shoulder and preserved detail.","prompt":"Apply a refined analogue halation treatment to the supplied photographic scene. Bright point sources and high-luminance edges should create a narrow warm red-orange glow that gently bleeds into adjacent darker areas, strongest around practical lights and specular highlights. Preserve the original subject, framing, exposure hierarchy and shadow detail. Keep the core highlight defined while the surrounding glow remains soft, organic and film-like. Add subtle fine-grain integration and natural colour response; avoid turning the image into a neon effect.","negative":"Large bloom clouds, clipped white highlights, red fog over the entire frame, lens flare streaks, loss of subject detail, heavy blur, digital glitch, text, watermark.","kind":"effect","bg":"#341b17","art":"radial-gradient(circle at 55% 45%,#fff2d0 0 4%,#ff6a2c 8%,#64211d 27%,#10151c 68%)","glow":"#ff6137","model":["Midjourney","DALL·E","Flux"],"tags":["Analogue","Highlight bloom","Film emulation"]},
{"id":20,"title":"Black Pro-Mist — Highlight Diffusion","category":"filter-effects","desc":"Low-contrast highlight diffusion with controlled bloom, lifted shadow ambience and preserved midtone structure.","prompt":"Recreate the optical character of a subtle 1/8 Black Pro-Mist lens filter. Diffuse only the brightest highlights into a soft, low-radius halo, gently lowering local contrast around practical lights while retaining deep black density and midtone texture. Skin, fabric and architectural edges must remain recognisable and reasonably sharp. Keep the bloom neutral-warm, restrained and physically plausible, as if captured through diffusion glass rather than blurred in post. Preserve original composition, colour relationships and exposure.","negative":"Milky grey veil, washed-out blacks, heavy soft focus, broad fog, glowing outlines on every edge, overexposed skin, smeared detail, text, watermark.","kind":"effect","bg":"#141a20","art":"radial-gradient(circle at 50% 48%,#fff 0 3%,#f0b98d 8%,#5c4a42 24%,#111820 65%)","glow":"#d59d7b","model":["Midjourney","DALL·E","Flux"],"tags":["Diffusion","Lens filter","Cinematic"]},
{"id":21,"title":"Prism Refraction — Spectral Light Split","category":"filter-effects","desc":"Controlled prismatic dispersion creating separated spectral highlights without obscuring the subject.","prompt":"Introduce a restrained optical prism effect as if a small precision glass prism sits just outside the camera axis. Split selected bright highlights into clean spectral bands with realistic angular displacement, subtle internal reflections and a few narrow refracted streaks. Keep the main subject crisp and compositionally dominant; spectral colour should occupy limited edge regions and never become a full-frame rainbow overlay. Preserve believable light direction, contrast and photographic texture. Premium experimental editorial photography, controlled optical imperfection.","negative":"Random rainbow gradients, full-frame colour wash, opaque geometric overlays, heavy blur, duplicated subjects, excessive flare, text, watermark.","kind":"effect","bg":"#0d1832","art":"linear-gradient(120deg,transparent 25%,#ff5d62 30%,#ffdb65 34%,#70e4c5 38%,#6f8eff 42%,transparent 48%)","glow":"#6d8cff","model":["Midjourney","DALL·E","Flux"],"tags":["Prism","Dispersion","Spectral"]},
{"id":22,"title":"Anamorphic Streak Flare — Horizontal Light","category":"filter-effects","desc":"Horizontal anamorphic flare streaks with coherent source alignment, subtle colour and controlled intensity.","prompt":"Add a restrained anamorphic lens flare treatment to a cinematic night photograph. A small number of intense point lights generate thin horizontal streaks aligned precisely with each source, with a cool blue-cyan core and faint warm fringe. Preserve the source lights as defined points, maintain the original focus plane and avoid covering faces or important product details. Include subtle internal ghost reflections only where optically plausible. Keep blacks rich, highlights controlled and the image photographic rather than science-fiction illustration.","negative":"Vertical starbursts, giant opaque blue bars, random flare orbs, excessive haze, washed-out blacks, streaks detached from light sources, text, watermark.","kind":"effect","bg":"#071521","art":"linear-gradient(180deg,transparent 44%,#174b72 48%,#b9eaff 50%,#2375a3 52%,transparent 57%)","glow":"#4baddb","model":["Midjourney","DALL·E","Flux"],"tags":["Anamorphic","Lens flare","Night photography"]},
{"id":23,"title":"Circular Polariser — Reflection Control","category":"filter-effects","desc":"Polarising-filter look that suppresses non-metallic glare while deepening skies and preserving natural colour.","prompt":"Render the scene as if photographed through a carefully rotated circular polarising filter. Reduce distracting reflections on non-metallic glass, water and glossy foliage while retaining natural specular cues where needed. Deepen blue sky and enrich foliage through reduced polarised glare, without globally increasing saturation. Preserve metallic reflections, realistic tonal transitions and natural exposure. Keep the effect directional and scene-dependent; avoid artificial clarity or HDR processing. The result should read as a genuine in-camera capture, not a digital contrast preset.","negative":"All reflections removed, metallic surfaces made matte, oversaturated sky, unnatural dark bands, HDR halos, crunchy clarity, colour cast, text, watermark.","kind":"effect","bg":"#173044","art":"linear-gradient(140deg,#0b375b,#73a8b8 42%,#d8e1d2 43%,#244a3c 75%)","glow":"#4f9fba","model":["Midjourney","DALL·E","Flux"],"tags":["Polarisation","Reflection control","Landscape"]},
{"id":24,"title":"Long Exposure — Motion Silk","category":"filter-effects","desc":"Long-exposure motion rendering with smooth directional trails and a stationary, sharply defined scene anchor.","prompt":"Transform moving water and passing light in the scene into a believable long-exposure photograph. Stationary architecture and foreground anchors remain crisp and geometrically unchanged, while moving water becomes smooth layered silk with continuous flow direction and moving lights form coherent trails. Maintain realistic exposure balance, natural highlight roll-off and fine static-scene detail. The motion blur must follow physical movement, not smear across unrelated surfaces. Tripod-mounted photographic character, neutral colour and controlled contrast.","negative":"Blurred buildings, random streaks, ghosted stationary objects, over-smoothed surfaces, synthetic motion vectors, blown highlights, text, watermark.","kind":"effect","bg":"#101f2b","art":"linear-gradient(165deg,#b5d3d9 0 12%,#284c5e 13% 31%,#9cb5b7 32% 39%,#152b3b 40% 100%)","glow":"#78aab9","model":["Midjourney","DALL·E","Flux"],"tags":["Long exposure","Motion blur","Photography"]},
{"id":25,"title":"Soft Focus Glow — Dream Lens","category":"filter-effects","desc":"Gentle optical softness around highlights with a readable focal plane and controlled atmospheric glow.","prompt":"Apply a delicate vintage soft-focus lens character while retaining a clearly resolved focal subject. Allow high-contrast highlights to feather softly into nearby tones and introduce a faint luminous veil in the brightest regions, but preserve facial structure, product edges and important text. Focus fall-off should feel optical and gradual rather than uniformly blurred. Use a subtle warm-neutral colour response, smooth highlight transitions and fine photographic grain. Keep the image elegant, tactile and legible.","negative":"Global gaussian blur, smeared facial features, loss of product silhouette, opaque fog, heavy bloom, plastic skin, low-resolution softness, text, watermark.","kind":"effect","bg":"#3a2e2b","art":"radial-gradient(circle at 48% 48%,#fff3dc 0 8%,#d7a78b 18%,#8a6c67 36%,#20202a 70%)","glow":"#d6a58a","model":["Midjourney","DALL·E","Flux"],"tags":["Soft focus","Optical glow","Portrait"]},
{"id":26,"title":"Duotone Separation — Ink Contrast","category":"filter-effects","desc":"Two-ink tonal mapping with controlled shadow/highlight assignment and retained graphic structure.","prompt":"Convert the image into a disciplined two-colour duotone print treatment. Map deep shadows to saturated midnight cobalt and highlights to warm vermilion-orange, with a carefully controlled intermediate transition rather than a muddy third colour. Preserve the original tonal hierarchy, silhouette clarity and important edge detail. Apply subtle ink density variation and a restrained printed-paper texture, keeping the composition legible at thumbnail scale. No additional graphic elements or typography; intentional contemporary editorial print aesthetic.","negative":"Full-colour remnants, uncontrolled gradients, muddy midtones, extra colours, posterised facial features, random halftone blocks, text, watermark.","kind":"effect","bg":"#101b44","art":"linear-gradient(130deg,#0b1e60 0 48%,#e95a24 49% 100%)","glow":"#e95a24","model":["Midjourney","DALL·E","Flux"],"tags":["Duotone","Print","Colour mapping"]},
{"id":27,"title":"Halftone Screen — CMYK Print Grain","category":"filter-effects","desc":"Structured halftone dot fields with consistent screen angles, tonal fidelity and controlled print registration.","prompt":"Apply a refined offset-print halftone treatment to the image. Translate continuous tones into coherent dot screens with consistent dot scale, clean round or elliptical dot geometry and controlled density across shadows, midtones and highlights. Use a disciplined limited CMYK-inspired palette with subtle, deliberate registration offset at selected high-contrast boundaries. Preserve the underlying composition and subject readability; halftone pattern should follow tonal information rather than appear as random polka dots. Add restrained uncoated-paper tooth.","negative":"Random dots, oversized polka dots, moiré interference, unreadable subject, excessive misregistration, noisy paper, extra typography, watermark.","kind":"effect","bg":"#20242a","art":"radial-gradient(circle,#f2a34d 1px,transparent 1.7px),linear-gradient(120deg,#173e7a,#e75b31)","glow":"#e75b31","model":["Midjourney","DALL·E","Flux"],"tags":["Halftone","Screenprint","CMYK"]},
{"id":28,"title":"Infrared False Colour — Spectral Remap","category":"filter-effects","desc":"False-colour infrared interpretation with channel remapping, tonal separation and preserved photographic detail.","prompt":"Reinterpret the supplied outdoor photograph as a carefully exposed false-colour infrared image. Map healthy foliage into pale luminous pinks and crimson, skies into deep cyan or near-black depending on tonal density, and built surfaces into neutral warm greys. Preserve believable material boundaries, leaf structure, cloud detail and natural perspective. The colour transformation should resemble a deliberate infrared capture and channel swap, not a random psychedelic filter. Maintain fine grain, controlled contrast and readable highlights.","negative":"Uniform magenta wash, neon rainbow, loss of foliage detail, posterisation, synthetic glow, altered geometry, text, watermark.","kind":"effect","bg":"#2c1839","art":"linear-gradient(130deg,#f2a0c5 0 38%,#692f85 39% 60%,#143f59 61% 100%)","glow":"#c76ba8","model":["Midjourney","DALL·E","Flux"],"tags":["Infrared","False colour","Photography"]},
{"id":29,"title":"T-Shirt Mockup — Front Flat Lay","category":"mockups","desc":"Top-down apparel presentation with accurate garment silhouette, print placement and believable fabric tension.","prompt":"Create a premium e-commerce flat-lay mockup of a single blank heavyweight cotton T-shirt, photographed perfectly overhead. Arrange the garment naturally but symmetrically, with sleeves evenly presented, collar shape accurate, hem visible and subtle gravity-led fabric folds. Preserve a realistic cotton jersey knit, stitch detail, ribbed neckline and true garment proportions. Leave the chest completely blank as a clean print-placement area. Use broad neutral studio light, soft contact shadow and a matte seamless background. No props, labels or styling clutter.","negative":"Model, mannequin, hanger, cropped garment, distorted sleeves, asymmetrical collar, floating shirt, logos, graphics, text, watermark.","kind":"mockup","bg":"#2a3036","art":"linear-gradient(135deg,#c4c9cb,#747e86 60%,#252b32)","glow":"#a8b4bd","model":["Midjourney","DALL·E","Flux"],"tags":["Apparel","Flat lay","E-commerce"]},
{"id":30,"title":"Hoodie Mockup — Invisible Form","category":"mockups","desc":"Ghost-form hoodie presentation that communicates garment volume, hood construction and natural drape.","prompt":"Produce a high-end ghost-mannequin mockup of a blank heavyweight pullover hoodie, front view at chest height. The garment holds a believable human-worn volume but no mannequin, neck insert or body is visible. Show hood depth, shoulder seams, drawcords, kangaroo pocket, ribbed cuffs and hem with accurate construction. Fabric is dense cotton fleece with weighty folds and subtle surface nap. Keep the chest graphic-free for later artwork placement. Neutral studio background, soft key and gentle fill, accurate colour and contact shadows.","negative":"Visible person, mannequin parts, floating hood, missing pocket, extra drawstrings, distorted cuffs, logos, print, text, watermark.","kind":"mockup","bg":"#292e35","art":"linear-gradient(135deg,#bbc1c5,#5e6871 55%,#151b21)","glow":"#9baab5","model":["Midjourney","DALL·E","Flux"],"tags":["Apparel","Ghost mannequin","Streetwear"]},
{"id":31,"title":"Curved-Brim Cap Mockup — Three-Quarter","category":"mockups","desc":"Structured baseball cap mockup with accurate panel geometry, curved peak, seam detail and blank front crown.","prompt":"Create a premium three-quarter studio product mockup of a structured six-panel baseball cap with a naturally curved brim. Show accurate crown volume, central front seam, panel stitching, eyelets, top button, underbrim and adjustable rear strap partially visible. The front crown must remain completely blank and flat enough for a logo placement, while following the fabric curvature. Use matte cotton twill with fine weave detail, realistic brim stiffness and soft directional studio lighting. Neutral seamless backdrop, grounded contact shadow, no model or props.","negative":"Flat unstructured cap, straight snapback brim, distorted crown, extra panels, floating peak, visible logo, text, watermark.","kind":"mockup","bg":"#1c2733","art":"linear-gradient(150deg,#aeb7bf,#303c4a 50%,#10161d)","glow":"#6f8799","model":["Midjourney","DALL·E","Flux"],"tags":["Headwear","Product mockup","Branding"]},
{"id":32,"title":"Tote Bag Mockup — Natural Canvas","category":"mockups","desc":"Reusable canvas tote with believable fabric sag, handle construction and undistorted artwork zone.","prompt":"Photorealistic product mockup of a single natural cotton canvas tote bag standing upright in a minimal studio. Show the full bag body, both handles, stitched seams, boxed lower corners and believable fabric sag under its own weight. Canvas weave is clearly visible with a dry unbleached finish. Keep the front panel clean and unobstructed as a defined artwork placement area; any folds should be subtle and must not distort that central zone. Soft side lighting, neutral warm-grey background, grounded shadow, straight-on three-quarter view.","negative":"Leather bag, glossy synthetic fabric, twisted handles, hidden base, extreme creases, printed artwork, extra objects, text, watermark.","kind":"mockup","bg":"#37342e","art":"linear-gradient(135deg,#d8c9a7,#9b8d70 65%,#3c3830)","glow":"#c1ad84","model":["Midjourney","DALL·E","Flux"],"tags":["Canvas","Accessories","Print placement"]},
{"id":33,"title":"Rigid Packaging Box — Three-Quarter Hero","category":"mockups","desc":"Premium rigid box mockup with precise board thickness, panel alignment and controlled surface finish.","prompt":"Render a premium rigid setup box as a commercial packaging mockup, viewed from a clean three-quarter angle that reveals the front, side and lid depth. Maintain square geometry, consistent board thickness, crisp folded edges and accurate lid-to-base alignment. Use matte uncoated paper with subtle fibre tooth and a restrained debossed blank panel reserved for branding. Large softbox reflections should describe the form without glare; include realistic contact shadow and a neutral studio sweep. No invented copy or brand marks.","negative":"Collapsed box, warped perspective, inconsistent lid, thin cardboard, glossy plastic, random text, logos, props obscuring panels, watermark.","kind":"mockup","bg":"#30343a","art":"linear-gradient(135deg,#d7d2c8 0 40%,#8c969e 41% 62%,#252c34 63%)","glow":"#b5bfc5","model":["Midjourney","DALL·E","Flux"],"tags":["Packaging","Rigid box","Brand presentation"]},
{"id":34,"title":"Cosmetic Bottle Mockup — Frosted Glass","category":"mockups","desc":"Minimal cosmetic bottle with controlled translucency, accurate closure geometry and a clean label zone.","prompt":"Create a premium cosmetic packaging mockup featuring one cylindrical frosted-glass bottle with a precise matte pump closure. Maintain believable wall thickness, softly diffused internal transmission, clean shoulder geometry and a stable flat base. Reserve a perfectly blank rectangular label area on the front, aligned to the bottle curvature without any generated typography. Use a pale neutral studio set, broad diffused key light, narrow rim highlight and subtle contact shadow. Commercial beauty product photography, clean reflections, realistic scale and no decorative props.","negative":"Distorted bottle neck, floating pump, opaque plastic, transparent water bottle, random label text, fake logos, clutter, harsh glare, watermark.","kind":"mockup","bg":"#d6d9d6","art":"linear-gradient(130deg,#f5f5ed,#aab9b7 45%,#697b7e)","glow":"#c5d8d6","model":["Midjourney","DALL·E","Flux"],"tags":["Cosmetics","Glass packaging","Label zone"]},
{"id":35,"title":"Business Card Mockup — Paper Stack","category":"mockups","desc":"Editorial stationery mockup with precise card proportions, paper edge detail and legible blank artwork surface.","prompt":"Photograph a small arrangement of premium business cards on a neutral studio surface. Use standard rectangular card proportions, crisp square corners, consistent stock thickness and a visible layered paper edge. Arrange one card as the hero with its face fully visible and parallel enough for later artwork placement; secondary cards may sit beneath at a restrained offset. Material is thick uncoated cotton paper with subtle tooth, clean edge shadows and no printed content. Soft directional light, controlled perspective, luxury brand identity presentation.","negative":"Rounded corners, warped card geometry, illegible generated typography, random logos, glossy plastic, excessive props, floating cards, watermark.","kind":"mockup","bg":"#30343a","art":"linear-gradient(135deg,#ece9df 0 45%,#a4a9aa 46% 70%,#343a42 71%)","glow":"#b7b8b3","model":["Midjourney","DALL·E","Flux"],"tags":["Stationery","Print design","Brand identity"]},
{"id":36,"title":"Poster Mockup — Gallery Wall","category":"mockups","desc":"Framed poster presentation with accurate print plane, controlled glass reflections and gallery-scale context.","prompt":"Create a refined gallery-wall mockup showing one large portrait-format poster in a slim, minimal frame. Camera is nearly frontal with only slight perspective, so the print plane remains undistorted and the entire artwork area is visible. Keep the poster completely blank, evenly lit and free of generated typography, reserved for supplied artwork. Include realistic frame depth, subtle glazing reflections that do not obscure the print, accurate wall contact shadow and a quiet architectural interior. Editorial art-direction, neutral materials, no distracting decor.","negative":"Crooked frame, distorted poster proportions, glare obscuring artwork, busy gallery clutter, invented poster content, random text, watermark.","kind":"mockup","bg":"#25292d","art":"linear-gradient(135deg,#e7e4dc 0 52%,#8b9298 53% 56%,#292f35 57%)","glow":"#c1c5c4","model":["Midjourney","DALL·E","Flux"],"tags":["Print","Interior","Presentation"]},
{"id":37,"title":"Smartphone Screen Mockup — App Interface","category":"mockups","desc":"Device presentation with accurate hardware proportions, straight screen plane and unobstructed interface area.","prompt":"Produce a premium product mockup of a modern unbranded smartphone, shown upright in a subtle three-quarter view against a clean studio background. Preserve realistic device proportions, slim symmetrical bezels, rounded display corners, precise side buttons and a believable camera cutout. The screen must be a perfectly clean, flat, blank display area for supplied UI artwork; do not invent icons, text or interface elements. Use controlled glass reflections that do not obscure the screen, soft contact shadow and high-end technology advertising lighting.","negative":"Recognisable brand logo, warped phone body, curved screen, excessive glare, generated interface text, random app icons, floating device, watermark.","kind":"mockup","bg":"#161f2b","art":"linear-gradient(140deg,#8998a5,#202b38 45%,#080d13)","glow":"#6d91b1","model":["Midjourney","DALL·E","Flux"],"tags":["Device","UI presentation","Technology"]},
{"id":38,"title":"Storefront Signage Mockup — Urban Facade","category":"mockups","desc":"Environmental brand application with perspective-correct signage, believable mounting and contextual scale.","prompt":"Create a photorealistic environmental branding mockup on a contemporary urban storefront. Show one clean rectangular fascia sign mounted above the entrance, with believable material thickness, fixing details, perspective and scale relative to doors and windows. Keep the sign face completely blank and evenly illuminated for later logo placement. Surrounding architecture should be understated and realistic, with natural overcast daylight, plausible glass reflections and grounded street-level camera position. The sign remains the clear focal point; avoid invented business names or extra advertising.","negative":"Floating sign, impossible mounting, warped lettering, random shop name, multiple competing signs, distorted architecture, dramatic fantasy lighting, watermark.","kind":"mockup","bg":"#252c32","art":"linear-gradient(130deg,#aeb8bd,#46545d 50%,#151c22)","glow":"#91a8b4","model":["Midjourney","DALL·E","Flux"],"tags":["Environmental","Signage","Brand application"]},
{"id":39,"title":"Subsurface Porcelain — Studio Sculpture","category":"3d-rendering","desc":"A translucent ceramic-like solid with soft light penetration and a refined glazed surface.","prompt":"A single sculptural object in translucent white porcelain, photographed in a controlled studio. Show a softly luminous body with subtle subsurface light transmission at thin edges, a restrained satin glaze, fine ceramic microtexture and a few naturally occurring kiln variations. Use a large diffused key light, narrow rim light and dark negative fill to describe curvature. Render with physically plausible roughness, Fresnel response, soft contact shadow and clean silhouette. Three-quarter camera, neutral seamless background, premium collectible-object presentation.","negative":"Plastic translucency, wax, glass clarity, mirror glaze, excessive surface defects, floating object, hard clipped highlights, text, watermark.","kind":"render","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Porcelain","Subsurface","Studio render"]},
{"id":40,"title":"Brushed Titanium — PBR Hero Asset","category":"3d-rendering","desc":"A precision titanium object with cool metallic response and directionally coherent reflections.","prompt":"A precision-machined titanium component as a clean hero asset, three-quarter view. Define a cool neutral metal base, fine directional machining marks, moderate metallic reflectance and controlled anisotropic roughness. Long strip lights should travel consistently along the brushed surfaces; dark flags create readable contrast without black clipping. Include realistic bevels, edge breaks, micro-scratches only at contact zones and grounded shadow. Physically based material response, accurate scale, crisp silhouette, neutral studio environment.","negative":"Chrome mirror finish, painted grey plastic, random scratches, inconsistent grain direction, melted bevels, floating object, text, watermark.","kind":"render","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Titanium","PBR","Machined"]},
{"id":41,"title":"Iridescent Thin Film — Interference Shader","category":"3d-rendering","desc":"Thin-film colour shifts driven by view angle, with controlled spectral transitions.","prompt":"Render a smooth sculptural surface coated in a physically plausible thin-film interference layer. Colour transitions should shift with viewing angle across cyan, violet, magenta and warm gold, while the underlying surface remains coherent and reflective. Keep the iridescence concentrated in grazing-angle regions, not as a flat rainbow gradient. Use soft studio panels and a dark reflection environment to reveal curvature. Preserve clean geometry, subtle micro-roughness and realistic specular roll-off; premium abstract product render.","negative":"Printed rainbow gradient, glitter, oil spill puddle, noisy colour banding, opaque paint, broken reflections, text, watermark.","kind":"render","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Iridescence","Shader","Spectral"]},
{"id":42,"title":"Soft-Body Translucent Silicone","category":"3d-rendering","desc":"A tactile silicone form with gentle deformation, matte translucency and realistic contact behaviour.","prompt":"A minimal soft-body object cast from translucent matte silicone, gently compressed where it contacts the floor. Show believable deformation, rounded tension folds, subtle subsurface scattering and a powder-soft surface with low-gloss highlights. Light from behind and above to reveal thickness without turning the material into glass. Keep the geometry physically coherent, with smooth transitions and realistic contact shadow. Macro product-render quality, restrained neutral palette, single object.","negative":"Hard plastic, wet rubber gloss, liquid puddle, impossible folds, sharp crystalline edges, excessive translucency, text, watermark.","kind":"render","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Silicone","Soft body","Translucency"]},
{"id":43,"title":"Cutaway Mechanical Assembly — Exploded View","category":"3d-rendering","desc":"A technically legible exploded product assembly with aligned parts and clear spatial hierarchy.","prompt":"Create a technically accurate exploded-view render of a compact mechanical assembly. Separate each component along a single clear axis with consistent spacing, preserve exact alignment and plausible assembly order, and keep fasteners and internal parts individually legible. Use a three-quarter orthographic-like camera, neutral light-grey studio background, restrained material differentiation and soft contact shadows beneath the parts. No labels or callouts; the geometry itself must communicate construction. Industrial design visualisation, crisp edges and realistic metal, polymer and elastomer response.","negative":"Randomly scattered components, overlapping parts, impossible connections, perspective distortion, decorative labels, invented text, missing fasteners, watermark.","kind":"render","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Exploded view","CAD visualisation","Assembly"]},
{"id":44,"title":"Volumetric Glass — Caustic Study","category":"3d-rendering","desc":"A thick glass object with focused caustics, accurate refraction and controlled internal reflections.","prompt":"A thick optical glass prism on a dark studio plinth, rendered with believable refractive depth. Show clear front and rear surfaces, subtle dispersion at high-contrast edges, internal reflections and concentrated caustic light projected onto the ground plane. Preserve geometric clarity and distinguish reflected studio panels from transmitted background shapes. Use a controlled single hard source with soft fill, physically plausible IOR behaviour and crisp contact shadow. Macro cinematic product visualisation.","negative":"Cloudy acrylic, opaque crystal, random rainbow streaks, melted geometry, excessive bloom, dirty glass, text, watermark.","kind":"render","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Glass","Caustics","Refraction"]},
{"id":45,"title":"Matte Ceramic — Microtexture Close-Up","category":"3d-rendering","desc":"A fine-grain ceramic coating with diffuse reflectance and restrained tactile imperfections.","prompt":"Render a close-up of a matte ceramic surface wrapping a simple curved industrial object. The finish should scatter light diffusely with very broad, soft highlights and no sharp specular streaks. Show fine mineral grain, subtle glaze pooling at a recessed edge and minute tonal variation that remains elegant rather than distressed. Use grazing softbox light to reveal texture, neutral colour management and realistic roughness. High-end material visualisation, no branding or scene clutter.","negative":"Glossy enamel, chalk dust, rough concrete, plastic, noisy bump map, repetitive procedural texture, text, watermark.","kind":"render","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Ceramic","Matte finish","Microtexture"]},
{"id":46,"title":"Translucent Layered Acrylic — Edge Light","category":"3d-rendering","desc":"Stacked acrylic plates with clean refraction, polished edges and precise spacing.","prompt":"A sculptural stack of three translucent coloured acrylic plates, precisely aligned but separated by small consistent air gaps. Show polished laser-cut edges, mild internal reflections, subtle refraction and colour density increasing where layers overlap. Use a controlled rim light through the plates and a soft overhead key to reveal thickness. Keep the surfaces clean, geometry exact and shadows physically grounded. Minimal studio render with a neutral background and carefully controlled colour separation.","negative":"Melted plastic, glass shards, random overlaps, opaque slabs, excessive rainbow dispersion, scratched dirty surfaces, text, watermark.","kind":"render","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Acrylic","Layering","Edge lighting"]},
{"id":47,"title":"Monumental Brutalist Atrium","category":"environments","desc":"A vast concrete interior with disciplined scale cues, directional daylight and material realism.","prompt":"A monumental brutalist atrium built from board-formed architectural concrete, viewed from a low human eye-level camera. Establish scale through a small number of architectural openings, a distant stair and one subtle human silhouette for reference. Tall shafts of overcast daylight enter from a high clerestory, revealing formwork grain, subtle casting seams and soft atmospheric depth. Maintain believable structural logic, consistent perspective, restrained tonal palette and quiet negative space. Architectural editorial photography, 24mm wide-angle character without exaggerated distortion.","negative":"Impossible structure, fantasy ornament, excessive fog, tiny scale cues, warped verticals, glossy concrete, crowds, signage, text, watermark.","kind":"environment","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Brutalism","Architecture","Daylight"]},
{"id":48,"title":"Rain-Soaked Neon Alley","category":"environments","desc":"A grounded night street with wet-surface reflections and controlled practical neon.","prompt":"A narrow contemporary urban alley at night after rainfall, photographed from street level. Wet asphalt and dark brick catch reflections from a small number of practical neon signs in restrained cyan and vermilion. Keep the light sources physically located in the scene so reflections align with them; puddles vary in size and surface roughness. Include layered foreground, middle-distance doorway and a distant vanishing point. Atmospheric moisture remains subtle, blacks retain detail and signage is abstract without legible words. Cinematic location photography.","negative":"Cyberpunk cliché overload, floating neon, random text, mirror-like entire road, heavy fog wall, oversaturated magenta wash, warped buildings, watermark.","kind":"environment","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Urban","Night","Wet surfaces"]},
{"id":49,"title":"Arid Limestone Courtyard","category":"environments","desc":"A sunlit architectural courtyard with warm stone, sharp shadows and measured spatial rhythm.","prompt":"A quiet arid-climate courtyard enclosed by pale limestone walls and simple geometric openings. Midday sun creates a precise shadow pattern across the stone floor, while warm reflected light lifts the shaded surfaces. Show subtle sediment bands, weather-softened edges, fine dust at joints and believable stone block scale. Frame with a balanced architectural composition, strong horizontal and vertical lines, one restrained plant for scale and no decorative clutter. Natural architectural photography, accurate perspective and warm neutral colour.","negative":"Artificial stucco, tropical foliage, excessive props, fantasy arches, distorted geometry, orange colour cast, text, watermark.","kind":"environment","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Limestone","Courtyard","Hard sunlight"]},
{"id":50,"title":"Misty Conifer Ridge — Atmospheric Depth","category":"environments","desc":"A layered forest landscape with controlled fog gradients and readable foreground detail.","prompt":"A remote conifer ridge at early morning, viewed across three distinct depth planes: sharply resolved foreground branches, a middle ridge with individual tree silhouettes and distant ridges dissolving gradually into cool mist. The fog follows valley contours rather than forming a uniform overlay. Use soft low-angle dawn light, natural muted greens and blue-grey distance, subtle moisture on needles and realistic atmospheric perspective. Wide landscape composition with a deliberate open sky region and fine photographic detail.","negative":"Uniform white fog, repeated tree clones, oversaturated greens, fantasy mountains, artificial blur gradient, text, watermark.","kind":"environment","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Landscape","Mist","Atmospheric perspective"]},
{"id":51,"title":"Coastal Concrete Observatory","category":"environments","desc":"A minimal coastal structure integrated with wind, sea spray and overcast light.","prompt":"A small modernist concrete observatory on an exposed rocky coastline, photographed in a wide architectural frame. The building uses simple monolithic forms, recessed glazing and a weathered salt-exposed concrete finish. Wind-driven sea spray catches the light near the rocks; the ocean remains textured and directional rather than smooth. Use overcast coastal daylight, subtle haze at the horizon and a low camera position that communicates exposure and scale. Preserve credible construction details and natural weathering.","negative":"Floating building, impossible cantilevers, tropical resort styling, dramatic fantasy waves, excessive spray, text, watermark.","kind":"environment","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Coastal","Concrete","Weathering"]},
{"id":52,"title":"Underground Transit Concourse","category":"environments","desc":"A functional subterranean public space with repeated structure and mixed practical lighting.","prompt":"A contemporary underground transit concourse after the commuter rush, captured from a central vanishing-point perspective. Repeated structural bays, ceiling services, tiled wall planes and a distant platform create strong depth. Cool overhead fluorescent light mixes with warmer wayfinding illumination, producing realistic colour contrast without a sci-fi atmosphere. Floor surfaces show restrained wear and reflected light; keep signs generic and unreadable. Architectural documentary photography, accurate scale, straight verticals and controlled exposure.","negative":"Futuristic spaceship, impossible corridors, crowded commuters, illegible generated typography, excessive lens flare, warped perspective, watermark.","kind":"environment","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Interior","Transit","Perspective"]},
{"id":53,"title":"Desert Dune Field — Wind-Carved Geometry","category":"environments","desc":"An expansive dune landscape with legible wind patterns and directional late-day light.","prompt":"A vast desert dune field at late afternoon, composed around a single sweeping foreground ridge leading into smaller receding forms. Wind creates fine parallel ripple marks that follow the dune curvature, with sharp crest edges and soft leeward shadow gradients. Use low warm sunlight from one side, restrained sand colour variation and distant atmospheric compression. No footprints or vegetation unless naturally implied. Photographic landscape realism, clean tonal separation and deliberate negative space.","negative":"Repeating identical dunes, orange oversaturation, plastic sand, footprints, fantasy structures, excessive grain, text, watermark.","kind":"environment","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Desert","Dunes","Natural forms"]},
{"id":54,"title":"Overgrown Industrial Greenhouse","category":"environments","desc":"A derelict glass-and-steel greenhouse reclaimed by controlled vegetation.","prompt":"An abandoned industrial greenhouse with a long steel frame, aged glazing and restrained vegetation reclaiming the floor and lower structure. Show realistic condensation, dirty glass panels, corrosion at joints and vines following plausible support paths. Diffused daylight filters through uneven panes, creating soft patches of light and a humid atmospheric depth. Preserve architectural perspective and a readable central aisle; vegetation should feel organic but not obscure the structure. Photorealistic environmental study.","negative":"Jungle engulfment, fantasy ruins, impossible plant growth, pristine new steel, opaque glass, heavy green colour cast, text, watermark.","kind":"environment","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Industrial","Glasshouse","Overgrowth"]},
{"id":55,"title":"Large Octabox — Controlled Portrait Key","category":"photography","desc":"A soft portrait lighting setup with defined catchlights and dimensional shadow falloff.","prompt":"Create a professional editorial portrait lit by one large octabox positioned 45 degrees camera-left and slightly above eye level, with restrained white bounce fill near camera-right. The key produces a broad soft highlight across the face, a gradual cheek shadow and one clean catchlight per eye. Preserve natural skin texture, realistic tonal transitions and accurate colour. Use a dark neutral background with subtle separation, medium close-up framing and an 85mm portrait-lens character. Retouched only lightly; retain pores and fine hair.","negative":"Ring-light flattening, multiple conflicting catchlights, plastic skin, beauty-filter smoothing, hard flash, clipped highlights, text, watermark.","kind":"photo","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Portrait","Softbox","Key light"]},
{"id":56,"title":"Hard Flash Editorial — Direct On-Camera","category":"photography","desc":"A punchy direct-flash fashion image with crisp shadows and honest surface texture.","prompt":"Photograph a contemporary fashion subject using direct on-camera flash in a dim urban interior. The flash creates crisp short shadows behind the subject, bright specular accents on reflective details and a rapid falloff into the darker room. Keep exposure balanced so skin and clothing retain texture rather than clipping. Use a candid slightly wide framing, direct gaze and natural posture; preserve realistic skin, fabric and ambient colour. Editorial snapshot energy, controlled grain and no artificial HDR.","negative":"Soft studio light, long cinematic shadows, over-smoothed skin, blown face, fake film borders, excessive red-eye, text, watermark.","kind":"photo","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Direct flash","Editorial","Fashion"]},
{"id":57,"title":"Golden-Hour Rim Light — Environmental Portrait","category":"photography","desc":"A warm edge-lit portrait with ambient fill and preserved skin-tone accuracy.","prompt":"Create an environmental portrait outdoors during the final minutes of golden hour. Place the sun behind and slightly to one side of the subject to form a warm rim along hair and shoulders, while open-sky fill keeps the face readable. Background highlights fall softly out of focus; retain environmental context without distracting detail. Use natural skin tones, believable lens contrast and subtle flare only if it originates from the sun position. Medium portrait framing, 50mm lens character, documentary editorial finish.","negative":"Orange skin, artificial halo outline, front-lit studio look, excessive lens flare, clipped sky, fake bokeh discs, text, watermark.","kind":"photo","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Golden hour","Rim light","Portrait"]},
{"id":58,"title":"Product Sweep — Gradient Background","category":"photography","desc":"A clean commercial product photograph with a seamless tonal sweep and grounded shadow.","prompt":"Photograph one premium consumer product centered on a seamless studio sweep that transitions subtly from a pale neutral near the floor to a slightly darker background above. Use a large overhead softbox as key, two narrow side cards for edge definition and a controlled negative fill to preserve shape. The product must have a crisp silhouette, accurate material response and a soft contact shadow directly beneath it. Keep reflections coherent with the studio setup and leave generous breathing room for a catalogue crop.","negative":"Floating product, inconsistent reflections, hard horizon line, clutter, fake labels, distorted geometry, clipped edges, watermark.","kind":"photo","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Product photography","Seamless","Studio"]},
{"id":59,"title":"Macro Focus Stack — Botanical Detail","category":"photography","desc":"A high-magnification natural subject with coherent sharpness and realistic optical falloff.","prompt":"Create a macro photograph of a single botanical subject at close range, with the primary reproductive structures and surface texture in crisp focus. Simulate a careful focus stack: the essential subject plane remains sharply resolved while the background falls into a smooth natural blur. Use soft diffused side light to reveal fine hairs, veins, pollen and subtle translucency without harsh specular glare. Maintain realistic scale, natural colour and a quiet uncluttered background.","negative":"Oversized pollen, artificial plastic petals, crunchy sharpening, inconsistent focus planes, synthetic bokeh, text, watermark.","kind":"photo","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Macro","Focus stacking","Botanical"]},
{"id":60,"title":"Low-Key Still Life — Negative Fill","category":"photography","desc":"A sculptural still life with controlled black levels and narrow highlight placement.","prompt":"Photograph a single sculptural object in a low-key studio using a narrow strip light as the principal source and black flags on both sides. Let most of the environment fall to deep black while preserving a readable silhouette and a few deliberate highlight bands that describe the material. Shadow detail should remain present but subdued; highlights must roll off smoothly. Use a three-quarter composition, stable camera and restrained tonal palette. Fine-art still-life photography, no theatrical smoke.","negative":"Crushed unreadable silhouette, multiple random highlights, broad flat fill, excessive bloom, floating object, noisy blacks, text, watermark.","kind":"photo","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Low key","Negative fill","Still life"]},
{"id":61,"title":"Window Light Interior — Natural Softness","category":"photography","desc":"A quiet interior photograph with directional window light and believable bounce.","prompt":"Photograph a minimal interior in late morning, with a large side window providing the dominant natural light. The window creates a broad directional patch across the floor and furniture, while warm wall bounce gently lifts shadow areas. Preserve realistic exposure differences between the window and interior, natural material colour and subtle dust-free clarity. Compose with strong architectural lines, a calm foreground-to-background progression and a 35mm lens character. Documentary interior photography, no artificial HDR.","negative":"Uniform ambient lighting, blown window, orange colour cast, distorted verticals, excessive styling props, fake sunbeams, watermark.","kind":"photo","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Interior","Window light","Natural light"]},
{"id":62,"title":"Night Portrait — Mixed Colour Temperature","category":"photography","desc":"A night-time portrait balancing cool ambient light and warm practical illumination.","prompt":"Create a cinematic night portrait on a real urban street, balancing cool blue ambient illumination from the open sky with a warm practical light source from a nearby shop window. The two colour temperatures should fall on different planes of the face and clothing in a physically coherent way. Keep skin tones credible, background lights softly defined and dark areas detailed. Medium close-up, eye-level camera, shallow but believable depth of field, restrained grain and candid expression.","negative":"Full neon colour wash, impossible lighting directions, oversaturated skin, excessive bokeh, heavy beauty retouch, text, watermark.","kind":"photo","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Night portrait","Mixed lighting","Urban"]},
{"id":63,"title":"Swiss Grid Poster — Asymmetric Information","category":"graphic-design","desc":"A strict editorial grid with asymmetrical balance and clear typographic hierarchy.","prompt":"Design a contemporary Swiss-influenced editorial poster on a portrait canvas. Build a disciplined modular grid with a strong left alignment, deliberate asymmetrical balance, one oversized typographic anchor and smaller supporting information blocks. Use generous negative space, precise baseline relationships and a restrained two-colour palette plus paper white. All text must be intentional and legible; use the exact supplied wording only, with no invented copy. Flat print-ready composition, sharp edges and subtle uncoated-paper texture.","negative":"Random text, decorative clutter, inconsistent alignment, excessive fonts, illegible microtype, gradients, mockup scene, watermark.","kind":"design","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Swiss design","Grid","Poster"]},
{"id":64,"title":"Experimental Condensed Typography — Monumental Type","category":"graphic-design","desc":"A typographic composition where condensed letterforms create architectural mass and rhythm.","prompt":"Create a typographic poster using a single monumental condensed sans-serif headline as the dominant visual structure. Treat letterforms as solid graphic architecture: tight but readable spacing, precise kerning, controlled line breaks and a strong vertical rhythm. Add only a small secondary information line and a restrained geometric accent. Preserve exact spelling of the supplied headline; do not invent additional words. Use a high-contrast black-and-bone palette with one vivid accent, crisp vector-like edges and print-ready flat artwork.","negative":"Mangled letters, random glyphs, decorative scripts, multiple competing headlines, 3D extrusion, shadows, watermark.","kind":"design","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Typography","Condensed","Editorial"]},
{"id":65,"title":"Bauhaus Geometric Cover — Primary Form","category":"graphic-design","desc":"A balanced geometric cover built from a small vocabulary of circles, bars and planes.","prompt":"Design a modernist graphic cover using only a controlled vocabulary of circles, rectangles, straight bars and diagonal planes. Establish a clear focal hierarchy through scale, overlap and negative space; every shape must contribute to balance rather than decoration. Use a limited primary palette with one neutral ground, precise edges and a subtle printed-paper finish. Reserve a clean title zone and render only the exact supplied title. Flat composition, no perspective or mockup presentation.","negative":"Random geometric confetti, gradients, shadows, 3D objects, unbalanced density, extra text, watermark.","kind":"design","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Bauhaus","Geometric","Cover"]},
{"id":66,"title":"Brutalist Editorial Layout — Dense Type Blocks","category":"graphic-design","desc":"A high-impact editorial page with rigid structure, compressed hierarchy and deliberate contrast.","prompt":"Create a brutalist editorial layout for a cultural publication. Use a strict column system, oversized heavy sans-serif headline, tightly set body copy blocks, sharp rules and one high-contrast image window. Density should feel intentional: align edges precisely, maintain readable line lengths and preserve clear hierarchy between headline, deck, metadata and body. Use black, warm white and a single signal colour. Insert only the supplied copy verbatim; if text is unavailable, leave clearly blank text areas rather than generating gibberish.","negative":"Random pseudo-text, decorative icons, soft gradients, loose alignment, illegible body copy, extra slogans, watermark.","kind":"design","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Brutalist","Editorial","Layout"]},
{"id":67,"title":"Minimal Identity System — Symbol and Wordmark","category":"graphic-design","desc":"A coherent brand identity board with scalable mark, typographic pairing and usage logic.","prompt":"Develop a minimal visual identity presentation for the supplied brand name and descriptor. Create one distinctive geometric symbol with a strong silhouette and balanced negative space, paired with a restrained wordmark using a complementary typeface. Show primary lockup, symbol-only mark, monochrome version and a compact colour palette as a clean flat brand board. Keep spacing, alignment and scale relationships consistent. Render the supplied brand name exactly; do not add slogans or invented copy.","negative":"Derivative famous logos, random glyphs, illegible wordmark, excessive gradients, mockup photography, ornamental details, watermark.","kind":"design","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Brand identity","Logo system","Presentation"]},
{"id":68,"title":"Duotone Editorial Image — Controlled Palette","category":"graphic-design","desc":"A photographic image mapped into two deliberate inks with retained tonal structure.","prompt":"Create an editorial image treatment using a strict two-ink palette: deep ultramarine for shadows and saturated vermilion for highlights, with controlled tonal interpolation. Preserve subject recognition, facial or object detail and the original light direction. The two colours should map according to luminance rather than arbitrary patches. Add a very subtle uncoated-paper grain and keep the composition clean enough for a magazine opener. No added typography or graphic overlays.","negative":"Full-colour remnants, random colour patches, muddy midtones, posterised anatomy, extra hues, noisy grain, watermark.","kind":"design","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Duotone","Colour mapping","Editorial"]},
{"id":69,"title":"Modular Icon Family — Consistent Stroke","category":"graphic-design","desc":"A coherent family of simple icons sharing grid, stroke, radius and optical weight.","prompt":"Design a set of six related interface icons for the supplied subject area. Each icon must share one consistent grid, stroke thickness, corner radius, cap style and optical weight. Use simple recognisable silhouettes with minimal internal detail; maintain equal visual density and alignment across the family. Present them in a clean evenly spaced grid on a plain background, monochrome only. Do not include labels or additional decorative elements; each icon should remain legible at small sizes.","negative":"Inconsistent stroke widths, mixed perspectives, gradients, shadows, overly detailed symbols, text labels, watermark.","kind":"design","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Iconography","Design system","Grid"]},
{"id":70,"title":"Risograph Print — Misregistration and Grain","category":"graphic-design","desc":"A tactile two- or three-ink print with controlled registration drift and paper texture.","prompt":"Create a contemporary risograph-style poster using two or three flat spot colours, visible paper tooth and a small, deliberate registration offset between ink layers. Preserve crisp underlying shapes while allowing slight edge misalignment and subtle ink density variation. Use a limited palette, clear typographic hierarchy and broad negative space. The print texture should be tactile but not obscure important wording or geometry. Exact supplied text only; no invented lettering.","negative":"Photographic gradients, CMYK gloss, severe registration errors, muddy overlaps, distressed grunge overload, random text, watermark.","kind":"design","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Risograph","Printmaking","Texture"]},
{"id":71,"title":"Photograph to Pixel Art — Scene Preservation","category":"transformations","desc":"A deliberate pixel-art conversion preserving layout, identity and object relationships.","prompt":"Transform the supplied photograph into premium hand-crafted pixel art. Preserve the original camera angle, framing, subject identity, pose, clothing, object placement, architecture and scene relationships. Rebuild all visual information with a consistent pixel grid, carefully clustered colour ramps, deliberate dithering only where useful and clean silhouette control. Pixel scale must remain consistent across foreground and background, with readable facial and material details. Do not crop, add objects or change the scene; no smoothing or vector-like gradients.","negative":"Changed identity, altered pose, new objects, mixed pixel sizes, blurry anti-aliasing, random noise, cropped scene, text, watermark.","kind":"transform","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Pixel art","Image transformation","Preservation"]},
{"id":72,"title":"Sketch to Photorealistic Product — Geometry Lock","category":"transformations","desc":"A faithful rendering of a supplied sketch with preserved silhouette and perspective.","prompt":"Convert the supplied product sketch into a photorealistic industrial design render. Preserve the exact outer silhouette, proportions, component positions, view angle and perspective from the drawing. Interpret only the implied surfaces as plausible materials, with accurate edge radii, seams and construction logic. Use a neutral studio environment and lighting that reveals form without redesigning it. Do not add controls, logos, labels or components that are not present in the sketch.","negative":"Redesigned geometry, changed perspective, extra controls, invented branding, impossible joins, decorative props, text, watermark.","kind":"transform","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Sketch to render","Product design","Geometry lock"]},
{"id":73,"title":"Day to Night — Lighting-Only Conversion","category":"transformations","desc":"A controlled time-of-day transformation preserving architecture, camera and scene geometry.","prompt":"Transform the supplied daylight photograph into a believable blue-hour or night scene while preserving the exact camera position, framing, architecture, landscape and object placement. Replace daylight illumination with coherent ambient twilight and practical light sources that illuminate only plausible surfaces. Maintain realistic exposure, shadow direction and reflections; windows and street lights should emit light without becoming clipped blobs. Keep material textures and all scene geometry unchanged. No new objects, signs or people.","negative":"Changed building geometry, shifted camera, invented street furniture, random glowing windows, oversaturated blue wash, fake stars, text, watermark.","kind":"transform","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Day to night","Lighting edit","Scene preservation"]},
{"id":74,"title":"Material Replacement — Surface-Only Edit","category":"transformations","desc":"A targeted material swap with geometry, lighting and composition held constant.","prompt":"In the supplied image, replace only the specified surface material with the requested material. Preserve exact object geometry, dimensions, edge details, seams, camera angle, perspective, shadows and all surrounding objects. Match the new material's roughness, reflectivity, texture scale and colour response to the existing light sources. Keep reflections and contact shadows physically coherent. Do not redesign, move, add or remove any component; all non-target regions remain unchanged.","negative":"Changed silhouette, altered proportions, shifted objects, inconsistent shadows, material applied to wrong surfaces, added decoration, text, watermark.","kind":"transform","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Material transfer","Local edit","Geometry preservation"]},
{"id":75,"title":"Illustration to 3D Clay Render — Form Fidelity","category":"transformations","desc":"A three-dimensional clay render retaining the exact illustration silhouette and layout.","prompt":"Convert the supplied illustration into a refined 3D clay render while preserving its original composition, silhouette, proportions and relative placement of every element. Interpret flat shapes as softly modelled volumes only where the drawing supports depth; retain graphic simplicity and avoid inventing hidden structures. Use a single matte clay material, broad soft studio light and a neutral background. Maintain the original camera viewpoint and keep all forms cleanly separated.","negative":"New elements, altered layout, excessive realism, shiny plastic, complex textures, changed silhouette, text, watermark.","kind":"transform","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["2D to 3D","Clay render","Form fidelity"]},
{"id":76,"title":"Seasonal Environment Shift — Weather Edit","category":"transformations","desc":"A weather transformation that changes atmosphere while retaining the original scene.","prompt":"Transform the supplied outdoor scene into the requested season and weather condition while preserving the camera, buildings, terrain, trees and object positions. Change only season-dependent elements such as foliage state, ground moisture, snow accumulation or atmospheric haze. Weather must interact physically with surfaces and light: snow rests on upward-facing planes, rain darkens exposed materials and fog reduces distant contrast. Keep the result documentary-realistic, with no new structures or props.","negative":"Changed architecture, arbitrary vegetation, impossible snow placement, uniform fog, fantasy weather, altered perspective, text, watermark.","kind":"transform","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Seasonal edit","Weather","Scene continuity"]},
{"id":77,"title":"Photo to Screenprint — Layer Separation","category":"transformations","desc":"A photographic conversion into distinct ink shapes with clear silhouette and overlap logic.","prompt":"Convert the supplied photograph into a limited-colour screenprint illustration. Reduce the image into three or four distinct ink layers based on clear tonal groupings, preserving the subject silhouette and essential structural detail. Use hard-edged shapes, restrained halftone only in selected midtone areas and deliberate overlap where inks combine. Keep the original composition and proportions; do not add lettering or decorative marks. Flat print-ready artwork with visible but subtle paper texture.","negative":"Airbrush gradients, excessive colours, random halftone, lost subject identity, new graphic elements, pseudo-text, watermark.","kind":"transform","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Screenprint","Photo conversion","Layering"]},
{"id":78,"title":"Object Extraction — Clean Transparent Cutout","category":"transformations","desc":"A clean isolated subject with alpha transparency and exact product geometry.","prompt":"Extract the primary subject from the supplied photograph and return it as a clean transparent-background cutout. Preserve exact geometry, proportions, labels, surface finish and small details; do not retouch away legitimate product features. Create a precise silhouette with natural edge antialiasing and no colour fringe, halo or residual background. Keep original lighting and material response. Centre the subject with even transparent padding; do not add a ground plane, cast shadow, checkerboard or replacement background.","negative":"Solid background, fake checkerboard, altered label, restyled product, missing small parts, edge halo, colour spill, added shadow, text, watermark.","kind":"transform","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Background removal","Transparency","Cutout"]},
{"id":79,"title":"Monumental Central Subject — Scale Hierarchy","category":"composition","desc":"A dominant central subject supported by restrained scale cues and negative space.","prompt":"Create a monumental editorial composition with one primary subject occupying the central visual axis. Establish scale through a small number of subordinate environmental elements that remain clearly secondary. Use a low camera angle, deliberate vertical structure and generous negative space around the silhouette. Light the subject with a defined key and subtle atmospheric separation; preserve readable surface detail and a strong value hierarchy. The image should feel intentional, spatially coherent and suitable for a premium campaign opener.","negative":"Competing focal points, clutter, arbitrary props, weak scale cues, flat lighting, cropped silhouette, random text, watermark.","kind":"composition","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Monumental","Scale","Hero composition"]},
{"id":80,"title":"Diagonal Tension — Dynamic Asymmetry","category":"composition","desc":"A controlled diagonal movement across the frame with balanced counterweights.","prompt":"Compose a dynamic editorial image around one dominant diagonal that guides the eye from foreground to background. Place the main subject off-centre and use secondary forms as counterweights rather than competing focal points. Maintain clear negative-space pockets, deliberate edge relationships and a readable silhouette. Use directional lighting to reinforce the movement and preserve realistic spatial depth. The result should feel energetic but structurally balanced, with no accidental tangencies or crowded corners.","negative":"Unrelated diagonals, centred static layout, cluttered edges, multiple equal focal points, arbitrary overlays, text, watermark.","kind":"composition","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Diagonal","Asymmetry","Dynamic"]},
{"id":81,"title":"Foreground Frame — Layered Depth","category":"composition","desc":"A scene composed through a natural foreground frame with clear subject separation.","prompt":"Build a layered composition using a softly out-of-focus foreground element to frame the main subject, a sharply resolved middle plane and a quieter background. The foreground must guide attention without obscuring the subject; maintain plausible depth of field and spatial continuity. Use overlapping forms, atmospheric separation and coherent light direction to create depth. Keep the primary subject visually dominant and preserve a clean path for the viewer's eye.","negative":"Foreground blocking subject, excessive blur, disconnected depth planes, flat staging, clutter, artificial vignette, text, watermark.","kind":"composition","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Layering","Depth","Framing"]},
{"id":82,"title":"Negative Space Editorial — Minimal Subject","category":"composition","desc":"A restrained composition where empty space carries equal visual weight to the subject.","prompt":"Create a minimal editorial composition with one small but clearly resolved subject placed deliberately within a large field of negative space. The empty area must remain clean and tonally controlled, not filled with gradients, texture noise or decorative elements. Use subtle directional light and a quiet palette to maintain visual tension. Preserve strong edge placement and enough breathing room for optional layout typography, but do not generate any text. Premium art-direction, precise balance and calm restraint.","negative":"Centred oversized subject, decorative clutter, busy background, random text, unnecessary props, excessive vignette, watermark.","kind":"composition","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Minimalism","Negative space","Editorial"]},
{"id":83,"title":"Rule-of-Thirds Landscape — Focal Anchor","category":"composition","desc":"A landscape with a clear horizon placement, foreground anchor and distant focal point.","prompt":"Compose a cinematic landscape using a clear rule-of-thirds structure: a deliberate horizon position, one foreground anchor and a distant focal feature placed off-centre. Lead-in lines should guide the eye naturally without appearing artificially arranged. Separate foreground, middle distance and background through realistic atmospheric perspective. Use directional natural light and preserve detail in both highlights and shadows. Wide photographic framing, balanced sky-to-land ratio and no unnecessary objects.","negative":"Centred horizon without intent, competing landmarks, artificial leading lines, oversaturated colour, fake fog, text, watermark.","kind":"composition","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Landscape","Rule of thirds","Focal hierarchy"]},
{"id":84,"title":"Symmetry with One Controlled Break","category":"composition","desc":"A near-symmetrical composition disrupted by one deliberate visual anomaly.","prompt":"Create a nearly symmetrical architectural or still-life composition with a clear central axis, repeated forms and carefully matched visual weight on both sides. Introduce exactly one controlled asymmetry—a colour accent, offset object or light interruption—to create tension without collapsing the overall balance. Maintain precise alignment, consistent scale and coherent perspective. Use disciplined lighting and a restrained palette. The asymmetry must read as intentional, not as an error.","negative":"Multiple random asymmetries, accidental misalignment, uneven perspective, clutter, excessive ornament, text, watermark.","kind":"composition","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Symmetry","Visual tension","Art direction"]},
{"id":85,"title":"Radial Composition — Orbiting Elements","category":"composition","desc":"A central focal form with orbiting secondary elements arranged on a coherent radial path.","prompt":"Design a radial composition around one central focal form, with a small number of secondary elements following a consistent circular or elliptical path. Vary scale and spacing to create rhythm while preserving clear separation and a readable centre. Use perspective and lighting consistently so every element belongs to the same spatial system. Keep the outer perimeter controlled and avoid tangencies at the frame edge. Graphic-concept art direction, precise geometry and restrained colour.","negative":"Random scatter, inconsistent orbit, overlapping clutter, unclear centre, arbitrary scale, text, watermark.","kind":"composition","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Radial","Spatial rhythm","Graphic composition"]},
{"id":86,"title":"Triptych Narrative — Three-Panel Continuity","category":"composition","desc":"A three-panel visual sequence with consistent subject identity and controlled progression.","prompt":"Create a three-panel triptych that communicates one visual idea through a clear progression from left to right. Maintain consistent subject identity, scale, material treatment and colour grade across all panels. Each panel should have a distinct but connected composition, with matching camera logic and a deliberate change in action, viewpoint or state. Use equal panel dimensions, clean gutters and no captions unless exact copy is supplied. Editorial sequence design, coherent visual continuity.","negative":"Different subjects between panels, inconsistent palette, unequal panel sizes, random gutters, repeated identical panels, invented captions, watermark.","kind":"composition","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Triptych","Sequence","Continuity"]},
{"id":87,"title":"Ceramic Glaze — Reactive Pooling","category":"materials","desc":"Glossy glaze with controlled kiln-driven colour movement.","prompt":"Photorealistic ceramic glaze test tile, deep cobalt base with restrained reactive turquoise pooling gathered naturally around shallow surface contours. Show a continuous vitreous coating, subtle orange-peel microtexture and a few fine kiln variations; glaze thickness changes should influence colour depth and reflectivity. Large softbox reflections travel smoothly across the curved tile, with a grazing strip light revealing the glaze boundary. Accurate fired-clay edge, neutral dark studio, macro material catalogue photography.","negative":"Dry chalk, plastic resin, metallic flakes, random splatter, exaggerated cracks, uneven focus, text, watermark.","kind":"material","bg":"#252a2e","art":"linear-gradient(135deg,#20252b,#68747b,#c0b8a8)","glow":"#8c9aa1","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Ceramic","Glaze","Reactive finish"]},
{"id":88,"title":"Terrazzo Composite — Aggregate Distribution","category":"materials","desc":"Mineral aggregate embedded in a honed cementitious matrix.","prompt":"A precision terrazzo material sample with small and medium marble, quartz and muted glass aggregates distributed through a warm off-white cement binder. Maintain believable aggregate scale, irregular but statistically balanced spacing, crisp cut edges and a honed low-sheen finish. Grazing light reveals tiny pits and aggregate boundaries without creating wet gloss. Show a thick rectangular slab in a neutral studio, physically plausible mineral variation and high-resolution macro detail.","negative":"Repeating confetti pattern, oversized stones, loose gravel, polished mirror gloss, plastic chips, floating particles, text, watermark.","kind":"material","bg":"#252a2e","art":"linear-gradient(135deg,#20252b,#68747b,#c0b8a8)","glow":"#8c9aa1","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Stone","Aggregate","Architectural finish"]},
{"id":89,"title":"Full-Grain Leather — Natural Patina","category":"materials","desc":"Supple leather with pore structure, crease memory and restrained sheen.","prompt":"Macro product-material photograph of full-grain dark oxblood leather. Resolve natural pore pattern, subtle grain variation, shallow crease memory and slight tonal burnishing at folded edges. The surface should absorb light with a soft semi-matte response; only raised grain catches narrow highlights. Include one relaxed fold to communicate thickness and suppleness, with realistic edge finishing and no embossed branding. Large diffused key, dark negative fill, true-to-scale texture.","negative":"Patent vinyl, plastic grain stamp, uniform synthetic texture, deep damage, excessive wrinkles, greasy gloss, text, watermark.","kind":"material","bg":"#252a2e","art":"linear-gradient(135deg,#20252b,#68747b,#c0b8a8)","glow":"#8c9aa1","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Leather","Grain","Patina"]},
{"id":90,"title":"Brushed Titanium — Precision Finish","category":"materials","desc":"Cool titanium with directional machining and restrained colour response.","prompt":"Photorealistic titanium sample with fine unidirectional brushing, cool neutral grey body colour and a subtle blue-violet tint only at grazing reflection angles. Preserve tight machining marks, consistent grain direction, clean bevel and realistic anisotropic specular response. Use two long strip lights at different angles to reveal the brushed structure without clipping highlights. Neutral industrial studio, precise macro focus, physically based metal shading.","negative":"Painted aluminium, rainbow oil slick, mirror chrome, coarse scratches, plastic, random grain direction, text, watermark.","kind":"material","bg":"#252a2e","art":"linear-gradient(135deg,#20252b,#68747b,#c0b8a8)","glow":"#8c9aa1","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Titanium","Machining","Anisotropy"]},
{"id":91,"title":"Bouclé Textile — Loop and Slub Structure","category":"materials","desc":"Tactile upholstery textile with irregular looped yarns.","prompt":"Extreme macro study of ivory bouclé upholstery fabric, showing irregular looped yarns, small slubs and varied fibre thickness with a dense but breathable construction. Side lighting creates tiny self-shadows between loops; maintain a soft dry hand and subtle tonal variation rather than a uniform fluffy pile. Include a gentle curved fold to show thickness and spring-back. Accurate textile scale, neutral warm studio, high-resolution commercial material photography.","negative":"Teddy fleece, terry towel, synthetic fur, uniform loops, oversized yarn, harsh sparkle, plastic sheen, text, watermark.","kind":"fabric","bg":"#252a2e","art":"linear-gradient(135deg,#20252b,#68747b,#c0b8a8)","glow":"#8c9aa1","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Bouclé","Upholstery","Yarn structure"]},
{"id":92,"title":"Cork Composite — Cellular Cut Surface","category":"materials","desc":"Natural cork cells with compressed granules and warm tonal variation.","prompt":"A macro material sample of natural cork composite, cut cleanly to expose fine cellular granules and compressed irregular pores. Warm honey, tan and muted brown variation should remain subtle and mineral-like. Show a lightly sanded face with dry matte response, a darker compressed edge and believable particle bonding. Raking light reveals topography without exaggerated depth; clean rectangular sample, neutral background, realistic scale.","negative":"Foam sponge, crumbly loose particles, printed cork pattern, wet shine, giant holes, repetitive noise, text, watermark.","kind":"material","bg":"#252a2e","art":"linear-gradient(135deg,#20252b,#68747b,#c0b8a8)","glow":"#8c9aa1","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Cork","Cellular","Bio-based material"]},
{"id":93,"title":"Powder-Coated Steel — Fine Texture","category":"materials","desc":"Durable matte coating with subtle orange-peel and clean metal edges.","prompt":"Studio macro photograph of a powder-coated steel panel in deep forest green. The coating has a fine, even microtexture with restrained orange-peel variation, low gloss and clean coverage around a machined folded edge. A narrow softbox reflection should diffuse across the coating, while the exposed cut edge reveals the underlying steel. Maintain realistic coating thickness, crisp corners and industrial finish quality.","negative":"Wet paint, rough sandpaper, plastic toy surface, rust, chips, uneven coating, mirror reflection, text, watermark.","kind":"material","bg":"#252a2e","art":"linear-gradient(135deg,#20252b,#68747b,#c0b8a8)","glow":"#8c9aa1","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Powder coat","Steel","Matte finish"]},
{"id":94,"title":"Lens Bloom — Controlled Highlight Expansion","category":"filter-effects","desc":"Optical bloom around selected highlights without losing edge structure.","prompt":"Apply a restrained photographic lens-bloom treatment to the supplied image. Bright practical lights and specular highlights should expand into soft luminous halos with a smooth intensity falloff, while midtones, shadows and fine subject edges remain crisp. Keep bloom local to high-luminance regions, preserve the original colour relationships and avoid washing the entire frame. Emulate a fast modern lens with subtle veiling flare, not a synthetic glow overlay.","negative":"Global haze, clipped whites, heavy blur, neon outlines, loss of contrast, coloured fog, duplicated light sources, text, watermark.","kind":"effect","bg":"#101b38","art":"linear-gradient(130deg,#071b46,#6b35a8 52%,#f18a42)","glow":"#6655bd","model":["Midjourney","DALL·E","Flux"],"tags":["Optical","Bloom","Highlight control"]},
{"id":95,"title":"Cross-Process Colour — Chemical Shift","category":"filter-effects","desc":"Analogue-inspired colour crossover with controlled channel bias.","prompt":"Regrade the image with a restrained cross-processed film character: cyan-biased shadows, slightly yellow-green highlights and rich but separated midtones. Preserve believable skin and neutral objects by keeping the colour crossover selective rather than uniformly tinting the frame. Add gentle contrast compression, subtle grain and a mild density shift in the deepest values. The result should feel like a deliberate laboratory film process, not a preset filter.","negative":"Uniform green cast, radioactive saturation, crushed blacks, posterisation, plastic skin, excessive grain, text, watermark.","kind":"effect","bg":"#101b38","art":"linear-gradient(130deg,#071b46,#6b35a8 52%,#f18a42)","glow":"#6655bd","model":["Midjourney","DALL·E","Flux"],"tags":["Colour grade","Analogue","Cross-process"]},
{"id":96,"title":"Tilt-Shift Miniature — Focus Plane","category":"filter-effects","desc":"Selective focus band that suggests miniature scale while retaining geometry.","prompt":"Create a convincing tilt-shift miniature effect on the supplied wide scene. Establish one narrow, smoothly graduated focus band across the intended focal area; foreground and background blur should increase progressively rather than abruptly. Slightly increase local contrast and colour density in focused regions to evoke a photographed scale model, while preserving architecture, object positions and perspective exactly. Keep the blur direction consistent with the scene's depth geometry.","negative":"Circular blur mask, hard focus boundary, warped buildings, changed perspective, excessive saturation, toy-like added details, text, watermark.","kind":"effect","bg":"#101b38","art":"linear-gradient(130deg,#071b46,#6b35a8 52%,#f18a42)","glow":"#6655bd","model":["Midjourney","DALL·E","Flux"],"tags":["Depth of field","Tilt-shift","Miniature illusion"]},
{"id":97,"title":"Infrared Foliage — False-Colour Response","category":"filter-effects","desc":"Surreal near-infrared tonal mapping with luminous vegetation.","prompt":"Transform the supplied outdoor photograph into a near-infrared-inspired image. Foliage shifts toward luminous pale pink or near-white according to its density, skies deepen toward charcoal or rich blue, and skin or built materials retain coherent tonal separation. Preserve the original scene geometry and lighting direction. Use controlled channel remapping, crisp local detail and restrained film grain; the result should resemble an intentional infrared photographic process.","negative":"Random colour replacement, uniform magenta wash, glowing outlines, altered objects, clipped foliage, painterly texture, text, watermark.","kind":"effect","bg":"#101b38","art":"linear-gradient(130deg,#071b46,#6b35a8 52%,#f18a42)","glow":"#6655bd","model":["Midjourney","DALL·E","Flux"],"tags":["Infrared","False colour","Landscape"]},
{"id":98,"title":"Anamorphic Streak Flare — Horizontal Source","category":"filter-effects","desc":"Directional horizontal flare with restrained spectral ghosts.","prompt":"Add a physically motivated anamorphic lens flare only to existing bright point or strip light sources. Create a narrow horizontal streak aligned to each source, with a bright central core, subtle cyan-to-amber spectral fringe and a few faint internal reflections. Flare intensity must respect source brightness and lens orientation; retain scene detail and avoid obscuring the subject. Cinematic optical character, controlled exposure, natural falloff.","negative":"Random diagonal beams, multiple invented lights, thick neon bars, giant flare discs, clipped subject, excessive rainbow, text, watermark.","kind":"effect","bg":"#101b38","art":"linear-gradient(130deg,#071b46,#6b35a8 52%,#f18a42)","glow":"#6655bd","model":["Midjourney","DALL·E","Flux"],"tags":["Lens flare","Anamorphic","Cinematic"]},
{"id":99,"title":"Duotone Mapping — Two-Ink Separation","category":"filter-effects","desc":"Two-colour tonal remapping with preserved image hierarchy.","prompt":"Convert the image into a disciplined two-ink duotone. Map deep shadows to a dark navy ink and highlights to warm coral, with a smooth but controlled transition through midtones. Preserve silhouette readability, facial structure and fine tonal hierarchy; avoid flattening all detail into two hard blocks. Add subtle uncoated-paper tooth and slight ink density variation while keeping edges clean and graphic.","negative":"Third accent colour, muddy midtones, random gradients, excessive halftone, lost contours, pseudo-text, watermark.","kind":"effect","bg":"#101b38","art":"linear-gradient(130deg,#071b46,#6b35a8 52%,#f18a42)","glow":"#6655bd","model":["Midjourney","DALL·E","Flux"],"tags":["Duotone","Print","Colour mapping"]},
{"id":100,"title":"Folded T-Shirt — Top-Down Apparel Mockup","category":"mockups","desc":"A natural folded garment presentation with accurate construction.","prompt":"Create a premium top-down e-commerce mockup of one heavyweight blank T-shirt folded into a compact, symmetrical retail presentation. Preserve realistic collar rib, shoulder seams, sleeve fold, double-stitched hem and dense cotton jersey texture. The folds should be gravity-consistent and slightly imperfect, with a soft contact shadow beneath the garment. Neutral warm-grey tabletop, overhead diffused light, no visible mannequin, no branding and no added graphics.","negative":"Floating garment, impossible folds, duplicated sleeves, distorted collar, thin fabric, logos, text, props, watermark.","kind":"mockup","bg":"#30353a","art":"linear-gradient(135deg,#d3d0c8,#68727a 55%,#171d23)","glow":"#a6afb5","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Apparel","Folded garment","E-commerce"]},
{"id":101,"title":"Sneaker Side Profile — Footwear Product Mockup","category":"mockups","desc":"Clean lateral footwear presentation with accurate sole and panel geometry.","prompt":"Present a single unbranded low-top trainer in a strict lateral three-quarter product view. Keep outsole thickness, toe spring, heel counter, lace routing, tongue, eyelets and panel seams mechanically plausible and consistent on both sides. Use matte neutral upper materials with clearly differentiated overlays, realistic rubber grain and controlled studio reflections. The shoe rests on a seamless pale-grey sweep with a soft grounded shadow; commercial catalogue sharpness.","negative":"Extra logos, impossible lacing, mismatched soles, warped toe box, floating shoe, duplicate footwear, exaggerated perspective, text, watermark.","kind":"mockup","bg":"#30353a","art":"linear-gradient(135deg,#d3d0c8,#68727a 55%,#171d23)","glow":"#a6afb5","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Footwear","Side profile","Product visual"]},
{"id":102,"title":"Wristwatch — Luxury Hero Mockup","category":"mockups","desc":"Precision watch product staging with legible case and strap details.","prompt":"Create a luxury product photograph of one unbranded wristwatch on a dark stone plinth. Maintain coherent case geometry, bezel, crown, lugs, crystal thickness, dial indices and strap attachment. Position the watch at a three-quarter angle so the case depth and dial remain readable; use a large soft key and narrow rim strip to reveal polished and brushed surfaces separately. Controlled reflections, accurate contact shadow, premium editorial restraint, no invented lettering.","negative":"Deformed hands, illegible dial marks, extra crowns, warped strap, floating watch, mirror glare hiding dial, logos, text, watermark.","kind":"mockup","bg":"#30353a","art":"linear-gradient(135deg,#d3d0c8,#68727a 55%,#171d23)","glow":"#a6afb5","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Watches","Luxury product","Hero shot"]},
{"id":103,"title":"Perfume Bottle — Glass and Cap Mockup","category":"mockups","desc":"Premium fragrance packshot with optical glass and precise closure.","prompt":"Stage one unbranded perfume bottle as a premium studio packshot. Define thick optical glass, accurate liquid meniscus, clean mould seams, a precisely fitted cap and subtle refraction through the base. Use a three-quarter camera angle, a pale gradient sweep and two controlled strip reflections that describe the bottle silhouette without obscuring its contents. Ground the object with a soft contact shadow; retain clean label-free surfaces and commercial realism.","negative":"Floating bottle, impossible liquid level, warped cap, cloudy glass, random labels, fingerprints, excessive bloom, text, watermark.","kind":"mockup","bg":"#30353a","art":"linear-gradient(135deg,#d3d0c8,#68727a 55%,#171d23)","glow":"#a6afb5","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Fragrance","Glass","Packshot"]},
{"id":104,"title":"Cosmetic Jar — Lid-Off and Product Texture","category":"mockups","desc":"Skincare container mockup with a controlled cream texture detail.","prompt":"Create a premium skincare product mockup featuring one cylindrical cosmetic jar with its lid placed beside it and a small controlled cream swatch. Preserve accurate threaded neck, lid fit, wall thickness and material transitions between frosted glass and satin polymer. The cream should form a smooth sculptural peak with realistic viscosity, not resemble foam. Soft high-key studio lighting, restrained beige palette, crisp contact shadows and clean label-free packaging.","negative":"Unrealistic lid threads, overflowing product, whipped foam, warped jar, random branding, cluttered props, text, watermark.","kind":"mockup","bg":"#30353a","art":"linear-gradient(135deg,#d3d0c8,#68727a 55%,#171d23)","glow":"#a6afb5","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Cosmetics","Packaging","Texture detail"]},
{"id":105,"title":"Laptop — Open Product Mockup","category":"mockups","desc":"Three-quarter hardware mockup with coherent screen, keyboard and hinge.","prompt":"Render a single premium unbranded laptop open at a natural working angle, viewed from a front three-quarter perspective. Maintain believable display thickness, hinge placement, keyboard spacing, trackpad proportions, port positions and consistent chassis geometry. Screen is a clean neutral placeholder with no interface or text. Use controlled studio strip lighting to separate anodised metal surfaces from the dark display glass; soft grounded shadow, precise industrial-design photography.","negative":"Extra keys, melted hinge, bent display, impossible ports, visible logos, invented interface text, floating device, watermark.","kind":"mockup","bg":"#30353a","art":"linear-gradient(135deg,#d3d0c8,#68727a 55%,#171d23)","glow":"#a6afb5","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Electronics","Hardware","Industrial design"]},
{"id":106,"title":"Poster on Concrete Wall — Environmental Mockup","category":"mockups","desc":"Wall-mounted print with accurate paper, scale and ambient contact.","prompt":"Place one portrait-format blank art poster on a raw concrete gallery wall. Keep the poster plane flat with subtle paper curl only at one lower corner, accurate paper thickness and a small natural cast shadow. Camera is nearly frontal with a slight perspective angle; wall pores and tonal variation remain secondary. Use soft directional daylight, restrained architectural styling and a completely blank print surface for later artwork placement.","negative":"Visible artwork, typography, frame unless requested, severe perspective distortion, floating paper, glossy plastic, excessive decor, watermark.","kind":"mockup","bg":"#30353a","art":"linear-gradient(135deg,#d3d0c8,#68727a 55%,#171d23)","glow":"#a6afb5","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Print","Wall display","Environmental"]},
{"id":107,"title":"Shopping Bag — Paper Handle Mockup","category":"mockups","desc":"Retail bag with accurate gussets, handle attachment and paper stock.","prompt":"Create a premium retail shopping-bag mockup in a three-quarter view. Show a rigid paper structure with a clearly defined front panel, side gusset, folded base and twisted-paper handles attached through reinforced eyelets. Use uncoated heavyweight stock with subtle fibre texture and slight edge compression. Bag stands upright on a neutral studio surface with a soft contact shadow; keep all panels blank and proportions realistic.","negative":"Impossible handles, missing gusset, paper behaving like fabric, random branding, glossy plastic, collapsed base, text, watermark.","kind":"mockup","bg":"#30353a","art":"linear-gradient(135deg,#d3d0c8,#68727a 55%,#171d23)","glow":"#a6afb5","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Retail packaging","Paper","Brand application"]},
{"id":108,"title":"Ceramic Mug — Handle and Glaze Study","category":"mockups","desc":"Product mockup with accurate handle attachment and glazed surface.","prompt":"Photograph one minimalist ceramic mug in a three-quarter view, handle fully visible and attached with a continuous ceramic transition. Use a satin off-white glaze with subtle kiln variation, a clean rim, believable wall thickness and a faint interior shadow. Place on a matte stone surface under broad diffused light with a narrow rim highlight. Keep the mug empty, unbranded and correctly grounded; premium homeware catalogue photography.","negative":"Broken handle, uneven rim, paper cup, excessive gloss, liquid, steam, logos, text, watermark.","kind":"mockup","bg":"#30353a","art":"linear-gradient(135deg,#d3d0c8,#68727a 55%,#171d23)","glow":"#a6afb5","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Homeware","Ceramic","Catalogue"]},
{"id":109,"title":"Subsurface Scattering — Translucent Wax Form","category":"3d-rendering","desc":"Soft light penetration through a warm translucent solid.","prompt":"Render a sculptural translucent wax object with physically plausible subsurface scattering. A broad warm key should penetrate thin edges and produce gentle internal light diffusion while thicker regions remain denser and less transmissive. Surface is softly matte with subtle mould imperfections and restrained specular response. Use a dark neutral studio, controlled rim separation, realistic contact shadow and a close three-quarter camera. Prioritise believable material thickness and smooth tonal falloff.","negative":"Glass transparency, wet plastic, self-emission, uniform translucency, wax drips unless specified, noisy shader, text, watermark.","kind":"3d","bg":"#101a2b","art":"radial-gradient(circle at 70% 20%,#e98a39,transparent 30%),linear-gradient(130deg,#17263b,#080c16)","glow":"#d18a49","model":["Blender","Cinema 4D","Unreal Engine","Flux"],"tags":["Subsurface scattering","Wax","Material rendering"]},
{"id":110,"title":"Soft-Body Simulation — Suspended Fabric","category":"3d-rendering","desc":"Gravity-driven cloth folds with coherent tension and contact.","prompt":"Create a physically plausible 3D cloth simulation of a single heavy fabric sheet suspended from two upper attachment points. Let gravity generate long tension folds, secondary creases and believable sag between anchors. Fabric thickness, weave scale and fold radius must remain consistent; self-collision should prevent intersections. Use a neutral studio backdrop and grazing light that reveals the fold topology without excessive gloss. Render a clear full silhouette with grounded physical logic.","negative":"Intersecting cloth, weightless floating, sharp paper folds, inconsistent weave scale, impossible tension, clipping, text, watermark.","kind":"3d","bg":"#101a2b","art":"radial-gradient(circle at 70% 20%,#e98a39,transparent 30%),linear-gradient(130deg,#17263b,#080c16)","glow":"#d18a49","model":["Blender","Cinema 4D","Unreal Engine","Flux"],"tags":["Simulation","Cloth","Dynamics"]},
{"id":111,"title":"Hard-Surface Product — Bevel Discipline","category":"3d-rendering","desc":"Industrial object render with controlled edge radii and manufacturing logic.","prompt":"Model and render a compact hard-surface industrial device with disciplined bevel hierarchy. Primary silhouette edges use small consistent radii, secondary panel breaks are finer, and functional openings align to plausible assembly logic. Separate anodised metal, matte polymer and glass display materials with distinct roughness and reflection behaviour. Use a three-quarter orthographic camera, large softboxes and a neutral studio floor. Every component should appear manufacturable and dimensionally coherent.","negative":"Melted bevels, random seams, impossible fasteners, inconsistent panel gaps, toy proportions, noisy reflections, logos, text, watermark.","kind":"3d","bg":"#101a2b","art":"radial-gradient(circle at 70% 20%,#e98a39,transparent 30%),linear-gradient(130deg,#17263b,#080c16)","glow":"#d18a49","model":["Blender","Cinema 4D","Unreal Engine","Flux"],"tags":["Hard surface","Product visualisation","Bevels"]},
{"id":112,"title":"Displacement Terrain — Eroded Rock Strata","category":"3d-rendering","desc":"Layered terrain with physically coherent erosion and scale.","prompt":"Generate a detailed 3D terrain fragment from layered sedimentary rock. Use displacement at multiple scales: broad geological strata, medium fractures and fine surface grain. Erosion follows gravity and material weakness, with believable ledges, undercuts and sediment deposits. Directional grazing light reveals relief; maintain a consistent scale reference through natural strata thickness and a clean neutral environment. Physically based stone roughness, no procedural repetition.","negative":"Noise-only surface, melted cliffs, random cracks, repeated tiling, impossible overhangs, miniature ambiguity, text, watermark.","kind":"3d","bg":"#101a2b","art":"radial-gradient(circle at 70% 20%,#e98a39,transparent 30%),linear-gradient(130deg,#17263b,#080c16)","glow":"#d18a49","model":["Blender","Cinema 4D","Unreal Engine","Flux"],"tags":["Terrain","Displacement","Geology"]},
{"id":113,"title":"Particle Instancing — Controlled Swarm","category":"3d-rendering","desc":"Instanced forms with deliberate density, trajectory and depth.","prompt":"Create a 3D particle-instancing study using one consistent geometric particle repeated through a controlled volumetric path. Vary scale and rotation within a narrow range, with density highest near the focal region and tapering toward the perimeter. Maintain collision-aware spacing and coherent depth cues; foreground particles are larger and sharper, distant particles smaller and softer. Use restrained studio lighting and a dark neutral background. The composition should feel designed, not randomly noisy.","negative":"Uniform grid, uncontrolled clutter, intersecting particles, inconsistent scale logic, motion blur hiding form, text, watermark.","kind":"3d","bg":"#101a2b","art":"radial-gradient(circle at 70% 20%,#e98a39,transparent 30%),linear-gradient(130deg,#17263b,#080c16)","glow":"#d18a49","model":["Blender","Cinema 4D","Unreal Engine","Flux"],"tags":["Instancing","Particles","Procedural"]},
{"id":114,"title":"Caustic Projection — Water-Focused Light","category":"3d-rendering","desc":"Focused light patterns projected through a shallow water volume.","prompt":"Render a physically plausible caustic-light study: a shallow transparent water volume focuses moving light into fine high-energy patterns on a matte pale surface below. Water surface remains subtle and optically coherent, with gentle ripples and correct refraction; caustics vary in scale and intensity according to surface curvature. Use a dark surrounding studio and a single directional source. Keep the light pattern crisp but not artificially sharp, with accurate attenuation.","negative":"Painted light texture, random neon lines, opaque water, impossible reflections, excessive sparkle, fog, text, watermark.","kind":"3d","bg":"#101a2b","art":"radial-gradient(circle at 70% 20%,#e98a39,transparent 30%),linear-gradient(130deg,#17263b,#080c16)","glow":"#d18a49","model":["Blender","Cinema 4D","Unreal Engine","Flux"],"tags":["Caustics","Water","Optics"]},
{"id":115,"title":"Procedural Knit — Stitch-Level Geometry","category":"3d-rendering","desc":"A knitted surface built from coherent interlocking yarn loops.","prompt":"Create a close 3D render of a knitted textile swatch using actual interlocking yarn-loop geometry rather than a flat texture. Maintain consistent yarn diameter, stitch tension, loop direction and row spacing. Soft fibre roughness and subtle fuzz catch grazing light; shadowing between loops communicates depth without becoming black cavities. Show a gently curved edge to reveal fabric thickness. Neutral studio, macro camera, physically based yarn shader.","negative":"Printed knit map, disconnected loops, inconsistent yarn thickness, plastic strands, oversized stitches, tangled geometry, text, watermark.","kind":"3d","bg":"#101a2b","art":"radial-gradient(circle at 70% 20%,#e98a39,transparent 30%),linear-gradient(130deg,#17263b,#080c16)","glow":"#d18a49","model":["Blender","Cinema 4D","Unreal Engine","Flux"],"tags":["Procedural material","Knit","Geometry"]},
{"id":116,"title":"Architectural Interior — Path-Traced Daylight","category":"3d-rendering","desc":"Interior visualisation with bounced light and material accuracy.","prompt":"Render a restrained contemporary interior using physically based materials and path-traced daylight. Establish a large side window as the primary light source; bounced illumination should lift shadow areas while preserving directional hierarchy. Distinguish honed stone, oiled timber, painted plaster and brushed metal through correct roughness and subtle imperfections. Maintain accurate architectural dimensions, vertical lines and plausible furniture scale. Camera at human eye height, natural exposure, no decorative over-styling.","negative":"Overexposed windows, impossible furniture, warped verticals, mirror-like plaster, excessive bloom, random decor, text, watermark.","kind":"3d","bg":"#101a2b","art":"radial-gradient(circle at 70% 20%,#e98a39,transparent 30%),linear-gradient(130deg,#17263b,#080c16)","glow":"#d18a49","model":["Blender","Cinema 4D","Unreal Engine","Flux"],"tags":["Archviz","Path tracing","Daylight"]},
{"id":117,"title":"Foggy Industrial Waterfront","category":"environments","desc":"Layered dockside structures with low-contrast atmospheric depth.","prompt":"Create a cinematic industrial waterfront at dawn, with cranes, warehouses and moored vessels receding through layered coastal fog. Foreground structures retain crisp material detail and damp surface reflections; distant forms lose contrast and saturation progressively according to atmospheric depth. Cool overcast light, subtle warm industrial practicals, calm water with restrained ripple scale. Wide establishing frame, documentary realism, coherent horizon and no readable signage.","negative":"Fantasy skyline, uniform fog wall, duplicated cranes, impossible reflections, oversaturated neon, random text, watermark.","kind":"environment","bg":"#182b39","art":"linear-gradient(130deg,#172d42,#7a593c 50%,#0d1725)","glow":"#7792a4","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Industrial","Waterfront","Atmosphere"]},
{"id":118,"title":"Japanese Narrow Street — Overcast Rain","category":"environments","desc":"Dense urban lane with wet materials and controlled signage.","prompt":"Depict a narrow contemporary Japanese urban side street after steady rain, viewed at pedestrian eye level. Wet asphalt and paving reflect existing shop lights with broken, perspective-correct highlights; concrete, tile, metal shutters and utility cables show believable age. Overcast blue-grey ambient light is balanced by a few warm interior sources. Keep signs abstract or unreadable, architecture coherent and the street lived-in rather than cyberpunk fantasy.","negative":"Tourist landmark clichés, invented legible text, excessive neon, mirror-smooth road, impossible cables, empty sterile street, watermark.","kind":"environment","bg":"#182b39","art":"linear-gradient(130deg,#172d42,#7a593c 50%,#0d1725)","glow":"#7792a4","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Urban","Rain","Japan-inspired"]},
{"id":119,"title":"Alpine Research Station — Snow Squall","category":"environments","desc":"Functional architecture under severe but believable mountain weather.","prompt":"Show a remote alpine research station during a passing snow squall. Low modern structures sit securely into a rocky snow-covered slope; wind direction is legible through drifting spindrift and snow accumulation on lee-facing edges. Visibility falls gradually into the mountain background, while near architecture remains readable. Cold diffuse sky light, restrained warm window glow, physically plausible snow depth and documentary landscape photography.","negative":"Impossible building placement, uniform whiteout, decorative aurora, tropical vegetation, floating snow, fantasy scale, text, watermark.","kind":"environment","bg":"#182b39","art":"linear-gradient(130deg,#172d42,#7a593c 50%,#0d1725)","glow":"#7792a4","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Alpine","Snow","Architecture"]},
{"id":120,"title":"Overgrown Concrete Infrastructure","category":"environments","desc":"Abandoned civil engineering with controlled vegetation succession.","prompt":"Create an abandoned concrete infrastructure site reclaimed gradually by vegetation: retaining walls, drainage channels and structural columns remain legible beneath moss, climbing plants and small saplings. Show water staining, mineral deposits and broken concrete only where structurally plausible. Soft overcast daylight and humid atmospheric depth; vegetation follows available soil and moisture rather than appearing randomly. Wide architectural composition, restrained colour, realistic decay.","negative":"Post-apocalyptic explosions, total ruin, random trees indoors, excessive vines, fantasy plants, text, watermark.","kind":"environment","bg":"#182b39","art":"linear-gradient(130deg,#172d42,#7a593c 50%,#0d1725)","glow":"#7792a4","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Abandoned","Concrete","Ecology"]},
{"id":121,"title":"Salt Flat at Blue Hour","category":"environments","desc":"Minimal horizon and reflective saline crust under twilight.","prompt":"Photograph an immense salt flat at blue hour with a low horizon and delicate polygonal salt crust in the foreground. A thin film of water creates subtle, physically aligned reflections of the twilight sky; distant mountains remain faint and atmospheric. Use a restrained cool palette with a narrow residual warm band near the horizon. Keep the frame quiet, expansive and geometrically precise, with realistic surface scale.","negative":"Ocean waves, mirror-perfect full reflection, oversized salt polygons, fantasy mountains, oversaturated sky, text, watermark.","kind":"environment","bg":"#182b39","art":"linear-gradient(130deg,#172d42,#7a593c 50%,#0d1725)","glow":"#7792a4","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Landscape","Minimal","Twilight"]},
{"id":122,"title":"Subterranean Metro Platform","category":"environments","desc":"Functional transit architecture with layered artificial illumination.","prompt":"Depict a modern subterranean metro platform from a clear central perspective. Repeating structural bays, platform edge, ceiling services and track geometry converge accurately toward a distant vanishing point. Cool overhead fluorescent illumination is interrupted by a few warmer practical sources; polished areas reflect light subtly while concrete and rubber remain matte. Include sparse human scale cues only if they remain secondary and anatomically credible. Documentary architectural photography.","negative":"Warped tracks, inconsistent columns, impossible signage, cyberpunk clutter, excessive reflections, distorted people, text, watermark.","kind":"environment","bg":"#182b39","art":"linear-gradient(130deg,#172d42,#7a593c 50%,#0d1725)","glow":"#7792a4","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Transit","Architecture","Perspective"]},
{"id":123,"title":"Tropical Storm Clearing — Coastal Cliffs","category":"environments","desc":"Post-storm landscape with directional cloud break and wet rock.","prompt":"Show rugged coastal cliffs immediately after a tropical storm begins to clear. Wet dark rock carries thin water sheen in crevices, while exposed surfaces remain rough and matte. A break in dense cloud sends one directional shaft of warm light across the sea and a section of cliff; the rest of the scene remains cool and overcast. Wind-driven cloud layers, credible wave scale and atmospheric perspective, cinematic landscape realism.","negative":"Calm sunny beach, giant fantasy waves, multiple suns, glowing rocks, artificial god rays, text, watermark.","kind":"environment","bg":"#182b39","art":"linear-gradient(130deg,#172d42,#7a593c 50%,#0d1725)","glow":"#7792a4","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Coast","Weather","Dramatic light"]},
{"id":124,"title":"Museum Storage Archive","category":"environments","desc":"Quiet conservation environment with dense shelving and controlled light.","prompt":"Create a realistic museum collection-storage archive with compact mobile shelving, labelled archival boxes and carefully protected objects. Repeating shelf geometry establishes depth; materials include powder-coated steel, acid-free board and neutral conservation textiles. Cool even overhead light, low glare, precise organisation and a calm institutional atmosphere. Any labels should remain abstract and unreadable; no identifiable artworks or legible collection data.","negative":"Messy warehouse, retail shelving, random artefacts, dramatic theatrical lighting, legible text, logos, watermark.","kind":"environment","bg":"#182b39","art":"linear-gradient(130deg,#172d42,#7a593c 50%,#0d1725)","glow":"#7792a4","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Interior","Archive","Institutional"]},
{"id":125,"title":"Glasshouse in Winter","category":"environments","desc":"Condensation, botanical structure and cold exterior light.","prompt":"Photograph a botanical glasshouse on a cold winter morning. Fine condensation and isolated droplets gather on the glazing, while interior tropical leaves create layered silhouettes at varying depths. Exterior daylight is cool and diffuse; warmer humid interior light gently separates the plants. Maintain accurate glass reflections and transmission, plausible plant scale and subtle moisture on metal framing. Quiet observational composition, no fantasy atmosphere.","negative":"Opaque fogged glass, excessive droplets, impossible plant anatomy, tropical sunlight, over-saturated greens, text, watermark.","kind":"environment","bg":"#182b39","art":"linear-gradient(130deg,#172d42,#7a593c 50%,#0d1725)","glow":"#7792a4","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Glasshouse","Botanical","Condensation"]},
{"id":126,"title":"Desert Service Road — Heat Haze","category":"environments","desc":"Long road perspective with physically graded thermal distortion.","prompt":"Create a remote desert service road stretching toward a low industrial horizon under intense midday heat. Asphalt surface shows realistic aggregate and subtle repairs; heat shimmer distorts only distant low-contrast regions above the road, not the entire frame. Sparse scrub and utility structures provide scale. Hard overhead sunlight, compact shadows, pale atmospheric wash and a restrained ochre-grey palette. Wide documentary composition.","negative":"Water mirage pools, fantasy dunes, uniform blur, bent horizon, excessive orange grading, text, watermark.","kind":"environment","bg":"#182b39","art":"linear-gradient(130deg,#172d42,#7a593c 50%,#0d1725)","glow":"#7792a4","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Desert","Heat haze","Infrastructure"]},
{"id":127,"title":"Macro Watch Detail — Focus Stacking","category":"photography","desc":"Tack-sharp mechanical detail across a shallow macro subject.","prompt":"Produce a high-magnification macro photograph of a mechanical watch movement, using focus stacking to keep the escapement, gear teeth and jewel bearings sharply resolved across depth. Preserve realistic metal machining, microscopic oil highlights and tiny edge burrs without inventing components. Diffused top light with a narrow grazing strip reveals surface finish; black flags control reflections. True macro scale, neutral colour, precise technical documentation.","negative":"Shallow blur hiding mechanisms, impossible gears, oversized dust, fantasy machinery, excessive sharpening halos, text, watermark.","kind":"photography","bg":"#242c34","art":"radial-gradient(circle at 80% 20%,#ff8a13,transparent 30%),linear-gradient(130deg,#252d36,#080b10)","glow":"#b18a62","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Macro","Focus stack","Technical detail"]},
{"id":128,"title":"Architectural Long Exposure — Moving People","category":"photography","desc":"Static building geometry with controlled pedestrian motion trails.","prompt":"Photograph a monumental public interior using a locked tripod and a long exposure. Architecture remains perfectly sharp with straight verticals and accurate perspective, while a small number of passing pedestrians become soft directional motion traces. Preserve natural light balance, realistic floor reflections and restrained contrast. Wide architectural lens, careful highlight retention and a clear structural focal point.","negative":"Blurred building, duplicated people, ghost limbs, warped verticals, excessive trails, artificial HDR, text, watermark.","kind":"photography","bg":"#242c34","art":"radial-gradient(circle at 80% 20%,#ff8a13,transparent 30%),linear-gradient(130deg,#252d36,#080b10)","glow":"#b18a62","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Long exposure","Architecture","Motion"]},
{"id":129,"title":"Hard Sun Still Life — Defined Shadow","category":"photography","desc":"Direct sunlight with crisp shadow geometry and tonal control.","prompt":"Create a minimalist still-life photograph under direct hard sunlight. One strong directional source produces crisp-edged shadows with a clearly readable direction and believable penumbra according to object distance. Preserve texture in illuminated surfaces and retain detail in shadow regions through subtle ambient fill. Use a restrained neutral set, deliberate object spacing and a fixed camera angle. High-end editorial still life, no artificial glow.","negative":"Multiple shadow directions, softbox look, clipped highlights, crushed shadows, random props, text, watermark.","kind":"photography","bg":"#242c34","art":"radial-gradient(circle at 80% 20%,#ff8a13,transparent 30%),linear-gradient(130deg,#252d36,#080b10)","glow":"#b18a62","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Hard light","Still life","Shadow design"]},
{"id":130,"title":"Rain-Splashed Portrait — Window Refraction","category":"photography","desc":"Portrait viewed through wet glass with controlled optical distortion.","prompt":"Photograph a close portrait through a rain-speckled window. Keep the subject's eyes and essential facial structure recognisable through a clear area of glass, while a few foreground droplets create local refraction and soft distortion near the frame edges. Cool exterior ambience and a restrained warm interior key establish separation. Shallow depth of field, natural skin texture and believable reflections on the glass.","negative":"Face obscured entirely, oversized droplets, duplicated features, artificial tear streaks, plastic skin, text, watermark.","kind":"photography","bg":"#242c34","art":"radial-gradient(circle at 80% 20%,#ff8a13,transparent 30%),linear-gradient(130deg,#252d36,#080b10)","glow":"#b18a62","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Portrait","Refraction","Rain"]},
{"id":131,"title":"Product Edge Light — Black-on-Black","category":"photography","desc":"Dark product photography with silhouette separation and preserved detail.","prompt":"Create a black-on-black studio product photograph of a dark object against a deep charcoal background. Use narrow rim lights on opposing sides to describe the silhouette, with a controlled overhead source revealing only essential surface detail. Negative fill maintains rich blacks without losing edge information. Keep reflections deliberate, material response accurate and contact shadow visible. Premium high-contrast commercial lighting.","negative":"Invisible silhouette, clipped white rims, grey washed background, random coloured lights, excessive bloom, text, watermark.","kind":"photography","bg":"#242c34","art":"radial-gradient(circle at 80% 20%,#ff8a13,transparent 30%),linear-gradient(130deg,#252d36,#080b10)","glow":"#b18a62","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Product","Low key","Rim lighting"]},
{"id":132,"title":"Overcast Fashion Editorial — Soft Tonality","category":"photography","desc":"Large-sky diffusion with natural skin and fabric rendering.","prompt":"Create a full-length fashion editorial portrait under bright overcast daylight. The sky acts as a broad diffused source, producing soft shadows and even skin transitions while preserving directional modelling. Render garment weave, drape and seam details accurately; keep skin texture natural and facial proportions unchanged. Use a muted urban architectural background, medium-format tonal character and a deliberate negative-space composition.","negative":"Beauty-dish contrast, wax skin, excessive retouching, altered body proportions, fake bokeh, text, watermark.","kind":"photography","bg":"#242c34","art":"radial-gradient(circle at 80% 20%,#ff8a13,transparent 30%),linear-gradient(130deg,#252d36,#080b10)","glow":"#b18a62","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Fashion","Overcast","Editorial"]},
{"id":133,"title":"Night Street Flash — Ambient Drag","category":"photography","desc":"Direct flash subject freeze combined with restrained background motion.","prompt":"Create a night street photograph using direct on-camera flash with a slightly slower shutter. The subject is crisply frozen, while distant traffic or practical lights show subtle directional ambient movement. Flash falloff should illuminate the foreground naturally and leave the background darker but readable. Preserve realistic skin texture, specular control and believable mixed colour temperatures. Candid editorial framing, no staged neon effects.","negative":"Entire frame blurred, subject ghosting, flat daylight, overexposed faces, random light trails, text, watermark.","kind":"photography","bg":"#242c34","art":"radial-gradient(circle at 80% 20%,#ff8a13,transparent 30%),linear-gradient(130deg,#252d36,#080b10)","glow":"#b18a62","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Flash","Night","Shutter drag"]},
{"id":134,"title":"Glassware Reflections — Black Flag Control","category":"photography","desc":"Transparent object photographed with deliberate reflection shaping.","prompt":"Photograph clear glassware in a studio using black and white flags to sculpt its contours. White cards create narrow edge reflections; black cards define transparent boundaries and preserve volume. Keep the liquid-free glass clean, with accurate rim thickness, refraction and subtle base distortion. Use a neutral gradient background, tripod precision and restrained exposure. Commercial optical product photography, crisp edges and no decorative styling.","negative":"Invisible glass, grey opaque body, random reflections, distorted rim, fingerprints, coloured liquid, text, watermark.","kind":"photography","bg":"#242c34","art":"radial-gradient(circle at 80% 20%,#ff8a13,transparent 30%),linear-gradient(130deg,#252d36,#080b10)","glow":"#b18a62","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Still life","Glass","Reflection control"]},
{"id":135,"title":"Environmental Portrait — Layered Practical Light","category":"photography","desc":"Naturalistic portrait lit by motivated sources within a real location.","prompt":"Create an environmental portrait inside a working studio or workshop, using existing practical lights as motivated sources. A soft key from a nearby window shapes the face; warm practicals provide background depth without competing with the subject. Maintain believable exposure ratios, natural skin texture and realistic mixed colour temperature. Include contextual tools and surfaces only as secondary detail, with a medium focal length and clear subject separation.","negative":"Unmotivated rim lights, multiple key directions, over-retouched skin, cluttered props, artificial cinematic haze, text, watermark.","kind":"photography","bg":"#242c34","art":"radial-gradient(circle at 80% 20%,#ff8a13,transparent 30%),linear-gradient(130deg,#252d36,#080b10)","glow":"#b18a62","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Portrait","Practical lighting","Environment"]},
{"id":136,"title":"Editorial Masthead — Custom Letterform","category":"graphic-design","desc":"A distinctive typographic title with controlled spacing and hierarchy.","prompt":"Design a high-end editorial masthead using one custom-drawn display wordmark and a disciplined supporting type system. Establish a clear hierarchy between masthead, issue metadata, headline and small captions; use optical kerning, consistent baseline logic and deliberate negative space. Treat letterforms as designed shapes with coherent stroke contrast and accurate counters. Two-colour print palette, grid-aligned layout, crisp vector edges. Use exact supplied copy only; otherwise leave text zones blank.","negative":"Pseudo-letters, misspellings, random filler copy, inconsistent kerning, decorative clutter, gradients, watermark.","kind":"graphic","bg":"#171b22","art":"linear-gradient(110deg,#171b22,#e55b10 70%,#11151c)","glow":"#e56a27","model":["Midjourney","DALL·E","Flux"],"tags":["Typography","Masthead","Editorial"]},
{"id":137,"title":"Modular Swiss Grid — Information Poster","category":"graphic-design","desc":"Precise typographic modules with asymmetrical grid tension.","prompt":"Create a Swiss-influenced information poster built on a modular grid. Use a strict column and baseline system, asymmetrical alignment, disciplined margins and a clear scale contrast between headline, subheads and data blocks. Limit the palette to black, warm white and one signal colour. Typography must be crisp and legible; if exact wording is not supplied, use empty text placeholders rather than invented copy. Flat print-ready vector aesthetic.","negative":"Random alignment, inconsistent margins, fake data, pseudo-text, decorative icons, 3D effects, watermark.","kind":"graphic","bg":"#171b22","art":"linear-gradient(110deg,#171b22,#e55b10 70%,#11151c)","glow":"#e56a27","model":["Midjourney","DALL·E","Flux"],"tags":["Swiss design","Grid","Poster"]},
{"id":138,"title":"Japanese Editorial Cover — Vertical Rhythm","category":"graphic-design","desc":"Minimal cover with vertical typography and balanced whitespace.","prompt":"Design a contemporary Japanese editorial cover using a restrained vertical typographic rhythm, carefully spaced kanji or supplied Latin text, and one abstract geometric image element. Keep the composition quiet and asymmetrical, with a deliberate relationship between title block, margins and image field. Use a limited ink palette and subtle uncoated-paper texture. Preserve exact supplied characters; if none are provided, leave the typography area blank rather than generating pseudo-language.","negative":"Incorrect characters, pseudo-Japanese text, crowded layout, decorative clichés, gradients, watermark.","kind":"graphic","bg":"#171b22","art":"linear-gradient(110deg,#171b22,#e55b10 70%,#11151c)","glow":"#e56a27","model":["Midjourney","DALL·E","Flux"],"tags":["Editorial","Japanese design","Cover"]},
{"id":139,"title":"Wayfinding System — Signage Family","category":"graphic-design","desc":"Consistent navigation signs with hierarchy and environmental legibility.","prompt":"Develop a coherent wayfinding signage family for a contemporary public building. Define consistent arrow geometry, pictogram stroke weight, type scale, mounting logic and colour coding across directional, identification and informational sign types. Show the family in a clean presentation grid with one realistic environmental application. Use exact supplied wording only; preserve legibility at distance and accessible contrast.","negative":"Inconsistent arrows, arbitrary icons, illegible microcopy, random colours, warped signs, fake logos, watermark.","kind":"graphic","bg":"#171b22","art":"linear-gradient(110deg,#171b22,#e55b10 70%,#11151c)","glow":"#e56a27","model":["Midjourney","DALL·E","Flux"],"tags":["Signage","System design","Pictograms"]},
{"id":140,"title":"Album Artwork — Abstract Sound Structure","category":"graphic-design","desc":"Square cover composition translating rhythm into visual form.","prompt":"Design square-format album artwork that translates rhythm and sonic texture into an abstract visual system. Build one dominant graphic motif from repeated bars, pulses or layered geometric forms, with controlled distortion and a clear focal hierarchy. Use a limited palette, strong edge discipline and deliberate negative space for optional title placement. Do not generate artist names, logos or illegible lettering; premium independent music-art direction.","negative":"Generic music symbols, random equaliser clichés, pseudo-text, excessive gradients, clutter, watermark.","kind":"graphic","bg":"#171b22","art":"linear-gradient(110deg,#171b22,#e55b10 70%,#11151c)","glow":"#e56a27","model":["Midjourney","DALL·E","Flux"],"tags":["Album art","Abstract","Music identity"]},
{"id":141,"title":"Packaging Dieline Presentation — Flat Layout","category":"graphic-design","desc":"Print-production layout with panels, folds and safe zones.","prompt":"Create a clean packaging dieline presentation for a simple folding carton. Show front, back, side panels, top and base in a flat orthographic layout with clearly differentiated cut lines, fold lines, bleed and safe-area guides. Maintain consistent panel dimensions and logical tab construction. Use neutral technical line weights and a restrained annotation system; all copy areas remain blank unless exact text is supplied.","negative":"Perspective mockup instead of flat dieline, impossible folds, missing glue tab, inconsistent dimensions, pseudo-text, watermark.","kind":"graphic","bg":"#171b22","art":"linear-gradient(110deg,#171b22,#e55b10 70%,#11151c)","glow":"#e56a27","model":["Midjourney","DALL·E","Flux"],"tags":["Packaging","Dieline","Production"]},
{"id":142,"title":"Variable Typography Specimen — Weight and Width","category":"graphic-design","desc":"A type specimen demonstrating controlled variable-font axes.","prompt":"Create a typographic specimen sheet showing one coherent variable type family across a deliberate range of weight and width settings. Align samples to a baseline grid and label axes only with supplied exact values. Show how counters, terminals and spacing change across the family while preserving character identity. Monochrome layout, crisp vector rendering, generous margins and no decorative imagery.","negative":"Unrelated typefaces, inconsistent glyph design, misspelled labels, random axis values, 3D text, watermark.","kind":"graphic","bg":"#171b22","art":"linear-gradient(110deg,#171b22,#e55b10 70%,#11151c)","glow":"#e56a27","model":["Midjourney","DALL·E","Flux"],"tags":["Type design","Specimen","Variable font"]},
{"id":143,"title":"Risograph Registration Shift — Two-Pass Print","category":"graphic-design","desc":"Layered spot inks with intentional but controlled misregistration.","prompt":"Create a two-colour risograph-style print using distinct spot-ink layers on uncoated paper. Show slight registration offset at selected edges, visible ink grain and subtle pressure variation while keeping the primary silhouette legible. Limit overprint behaviour to plausible colour mixing where inks overlap. Preserve clean shapes and a strong composition; no fake distressed damage or random extra colours.","negative":"Photographic gradients, perfect digital edges, excessive misregistration, muddy overprint, random speckles, pseudo-text, watermark.","kind":"graphic","bg":"#171b22","art":"linear-gradient(110deg,#171b22,#e55b10 70%,#11151c)","glow":"#e56a27","model":["Midjourney","DALL·E","Flux"],"tags":["Risograph","Print texture","Spot colour"]},
{"id":144,"title":"Sketch to Technical Product Render — Design Lock","category":"transformations","desc":"Convert a concept sketch while retaining its exact design decisions.","prompt":"Transform the supplied product sketch into a clean photorealistic industrial-design render. Preserve the original silhouette, proportions, feature placement, openings, controls and viewpoint; do not redesign ambiguous areas. Interpret linework as coherent manufactured surfaces with plausible part boundaries, bevels and materials. Use a neutral studio, soft key light and crisp edge definition. Any unresolved sketch marks should remain conservative rather than becoming invented mechanisms.","negative":"Changed silhouette, extra buttons, invented vents, altered proportions, new branding, dramatic camera change, text, watermark.","kind":"transform","bg":"#20182e","art":"linear-gradient(130deg,#17122c,#7447bc 50%,#12151e)","glow":"#9473d0","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Sketch conversion","Industrial design","Geometry lock"]},
{"id":145,"title":"Portrait to Graphite Drawing — Tonal Fidelity","category":"transformations","desc":"Pencil translation preserving likeness and facial structure.","prompt":"Convert the supplied portrait into a refined graphite drawing while preserving facial identity, expression, head angle, hairstyle and proportions. Build form through layered graphite values, directional hatching and soft blending only where appropriate. Keep paper grain visible, highlights clean and darkest accents concentrated in the eyes, hair and cast shadows. Maintain the original crop and lighting direction; avoid idealising or changing features.","negative":"Changed identity, beautification, cartoon outlines, charcoal smears everywhere, altered expression, added accessories, text, watermark.","kind":"transform","bg":"#20182e","art":"linear-gradient(130deg,#17122c,#7447bc 50%,#12151e)","glow":"#9473d0","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Portrait","Graphite","Identity preservation"]},
{"id":146,"title":"Daylight to Sodium-Vapour Night","category":"transformations","desc":"Relight an existing scene with motivated night illumination.","prompt":"Transform the supplied daytime scene into a believable urban night scene while preserving architecture, camera position, object placement and weather. Replace daylight with a dark ambient base and motivated sodium-vapour practicals; warm pools of light should fall off according to distance and surface orientation. Windows and reflective materials respond coherently, with shadows deepening naturally. Retain readable detail without turning the scene into a neon fantasy.","negative":"Changed buildings, invented light sources, uniform orange tint, impossible shadows, excessive neon, altered perspective, text, watermark.","kind":"transform","bg":"#20182e","art":"linear-gradient(130deg,#17122c,#7447bc 50%,#12151e)","glow":"#9473d0","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Relighting","Day-to-night","Continuity"]},
{"id":147,"title":"Photograph to Woodcut — Carved Line Logic","category":"transformations","desc":"Translate tonal structure into carved marks and inked relief.","prompt":"Convert the supplied photograph into a traditional woodcut print. Preserve the main subject silhouette and compositional structure, translating tonal regions into directional carved lines, cross-hatching and solid ink masses. Line direction should follow form and volume; highlights are created by unprinted paper rather than airbrush gradients. Use one dark ink on warm paper with subtle relief texture. No added lettering or ornamental border.","negative":"Smooth digital gradients, random hatch direction, excessive tiny noise, lost silhouette, extra colours, pseudo-text, watermark.","kind":"transform","bg":"#20182e","art":"linear-gradient(130deg,#17122c,#7447bc 50%,#12151e)","glow":"#9473d0","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Printmaking","Woodcut","Linework"]},
{"id":148,"title":"Material Refinish — Matte to Polished","category":"transformations","desc":"Change surface finish while preserving object geometry and lighting.","prompt":"Modify only the surface finish of the supplied object from matte to polished while preserving exact geometry, camera, labels, seams and environment. Recalculate reflection behaviour according to the new roughness: broad diffuse highlights become tighter and more defined, while the base colour and material identity remain consistent. Existing light sources must remain the only reflection sources. Keep contact shadows and all non-target regions unchanged.","negative":"Geometry changes, invented reflections, mirror chrome, colour replacement, new seams, altered labels, text, watermark.","kind":"transform","bg":"#20182e","art":"linear-gradient(130deg,#17122c,#7447bc 50%,#12151e)","glow":"#9473d0","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Material edit","Roughness","Local modification"]},
{"id":149,"title":"Photo to Flat Vector Icon — Silhouette Reduction","category":"transformations","desc":"Reduce a subject into a clear scalable icon without losing recognition.","prompt":"Translate the supplied subject photograph into a single flat vector-style icon. Preserve the most recognisable outer silhouette and essential internal features, reducing secondary detail into a small number of clean geometric regions. Use consistent stroke logic or solid fills, balanced optical weight and a transparent or plain background. The result must remain legible at small sizes and should not add decorative framing or text.","negative":"Excessive detail, gradients, 3D shading, inconsistent stroke, changed subject identity, pseudo-text, watermark.","kind":"transform","bg":"#20182e","art":"linear-gradient(130deg,#17122c,#7447bc 50%,#12151e)","glow":"#9473d0","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Vectorisation","Icon","Simplification"]},
{"id":150,"title":"Interior Declutter — Architectural Preservation","category":"transformations","desc":"Remove selected clutter while preserving the photographed room.","prompt":"Edit the supplied interior photograph to remove only the specified clutter items. Reconstruct occluded wall, floor and furniture surfaces using consistent perspective, texture scale, lighting and contact shadows. Preserve all architecture, fixed fittings, furniture dimensions, camera position and overall colour grade. Do not replace the room or introduce new decor. The final result should read as an unedited architectural photograph.","negative":"Changed layout, altered furniture, invented decor, repeated textures, warped lines, inconsistent shadows, text, watermark.","kind":"transform","bg":"#20182e","art":"linear-gradient(130deg,#17122c,#7447bc 50%,#12151e)","glow":"#9473d0","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Inpainting","Interior","Scene preservation"]},
{"id":151,"title":"Photo to Cyanotype — Prussian Blue Chemistry","category":"transformations","desc":"Photographic conversion into a high-contrast cyanotype print.","prompt":"Convert the supplied image into a cyanotype-inspired photographic print. Use characteristic Prussian blue tonal fields and pale exposed highlights, retaining a recognisable subject and controlled midtone detail. Introduce subtle paper fibre, slight chemical unevenness and soft edge variation without obscuring the image. Keep the original crop and subject placement; no additional botanical motifs or decorative borders.","negative":"Generic blue filter, digital gradient, excessive stains, lost subject detail, added flowers, pseudo-text, watermark.","kind":"transform","bg":"#20182e","art":"linear-gradient(130deg,#17122c,#7447bc 50%,#12151e)","glow":"#9473d0","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Cyanotype","Photochemical","Print"]},
{"id":152,"title":"Object to Isometric Illustration — Projection Lock","category":"transformations","desc":"Convert a photographed object into a clean isometric graphic.","prompt":"Translate the supplied object into a precise isometric illustration while preserving its identifiable component layout and relative proportions. Establish consistent 30-degree axes, parallel edges and a coherent light direction; simplify surface detail into clean colour planes and selective linework. Keep every component attached in its original relationship. Use a restrained palette and flat background, with no invented labels or exploded parts.","negative":"Perspective drift, mixed projection angles, detached components, altered proportions, gradients, pseudo-text, watermark.","kind":"transform","bg":"#20182e","art":"linear-gradient(130deg,#17122c,#7447bc 50%,#12151e)","glow":"#9473d0","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Isometric","Illustration","Projection"]},
{"id":153,"title":"Seasonal Product Styling — Set Replacement","category":"transformations","desc":"Change the surrounding set while keeping the hero product unchanged.","prompt":"Retain the supplied hero product exactly, including geometry, colour, finish, labels and camera angle, while replacing only the surrounding set with a restrained seasonal styling environment. New props must remain secondary, correctly scaled and physically grounded. Match contact shadows, reflections and colour temperature to the product's original lighting. Keep the product as the sole focal point and preserve its silhouette.","negative":"Modified product, new branding, props overlapping product, inconsistent shadows, excessive seasonal clichés, text, watermark.","kind":"transform","bg":"#20182e","art":"linear-gradient(130deg,#17122c,#7447bc 50%,#12151e)","glow":"#9473d0","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Product edit","Set design","Object preservation"]},
{"id":154,"title":"Low-Angle Monumental Architecture — Vertical Force","category":"composition","desc":"Use converging verticals and scale cues to create architectural monumentality.","prompt":"Compose a monumental architectural photograph from a low camera position, using strong vertical lines and carefully controlled convergence to amplify height. Include one small scale cue near the base without making it a focal subject. Maintain plausible lens perspective, readable facade detail and clean edge relationships. Overcast directional light reveals surface relief; the sky remains a quiet negative-space field. Precise architectural editorial framing.","negative":"Random tilted camera, excessive barrel distortion, competing landmarks, cluttered foreground, fake scale cues, text, watermark.","kind":"composition","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Architecture","Low angle","Scale"]},
{"id":155,"title":"Layered Still Life — Foreground to Background Rhythm","category":"composition","desc":"Arrange objects in depth with a clear hierarchy and controlled overlap.","prompt":"Build an editorial still-life composition from a small family of related objects arranged across three depth planes. One hero object anchors the middle plane; foreground and background elements create rhythm through controlled overlap, scale variation and negative space. Keep every object fully readable where necessary and prevent accidental tangencies. Use one coherent light direction and a restrained material palette.","negative":"Random scatter, equal focal weight, hidden hero object, inconsistent shadows, crowded frame, text, watermark.","kind":"composition","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Still life","Layering","Hierarchy"]},
{"id":156,"title":"Circular Crop — Contained Visual Field","category":"composition","desc":"A circular image boundary with deliberate internal balance.","prompt":"Create a composition contained within a precise circular visual field. Keep the primary subject and all essential details comfortably inside the circle, with secondary forms arranged to reinforce its curvature and balance. Outside the circle remains a clean contrasting field. Maintain consistent perspective and avoid tangencies where forms meet the circular boundary. Graphic editorial art direction, controlled negative space and crisp edges.","negative":"Square crop, clipped subject, accidental edge tangencies, clutter outside circle, inconsistent scale, text, watermark.","kind":"composition","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Circular","Framing","Graphic"]},
{"id":157,"title":"Oversized Typography as Architecture","category":"composition","desc":"Treat large letterforms as spatial structures within the frame.","prompt":"Construct an editorial composition in which oversized supplied letterforms act as architectural planes around a smaller focal subject. Preserve exact spelling and character design; letters may crop at the frame edges but must remain structurally coherent. Establish depth through overlap, scale and directional shadow, while the subject remains clearly separated. Use a restrained two- or three-colour system and strong grid logic.","negative":"Misspelled text, pseudo-letters, random fonts, illegible overlap, competing focal points, decorative clutter, watermark.","kind":"composition","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Typography","Scale","Spatial design"]},
{"id":158,"title":"Top-Down Geometry — Orthographic Order","category":"composition","desc":"A flat-lay arrangement governed by precise spacing and alignment.","prompt":"Create a top-down orthographic composition of a small collection of objects arranged on a clean surface. Use deliberate spacing, parallel alignment and controlled rotations to create a measured rhythm; preserve true object proportions and avoid perspective distortion. One object establishes the primary axis, while supporting items create a balanced but not mechanical arrangement. Soft overhead light, subtle contact shadows and a restrained palette.","negative":"Three-quarter camera, inconsistent object scale, random overlap, floating items, hard directional shadows, text, watermark.","kind":"composition","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Flat lay","Orthographic","Order"]},
{"id":159,"title":"Frame Within Frame — Architectural Threshold","category":"composition","desc":"Use a doorway or structural opening to isolate the subject.","prompt":"Compose the scene through a strong architectural threshold such as a doorway, arch or corridor opening. The frame structure occupies the foreground and directs attention toward a clearly separated subject in the middle distance. Maintain consistent perspective, layered tonal contrast and a natural falloff of detail. The opening should feel spatially real, not like a graphic border. Restrained cinematic light and deliberate negative space.","negative":"Flat border overlay, competing frames, blocked subject, impossible perspective, excessive vignette, text, watermark.","kind":"composition","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Framing","Architecture","Depth"]},
{"id":160,"title":"Single Accent Colour — Monochrome Hierarchy","category":"composition","desc":"A mostly monochrome frame with one precisely placed chromatic accent.","prompt":"Design a composition in near-monochrome values with exactly one saturated accent colour assigned to the primary focal element. All other elements remain within a controlled neutral range, differentiated by value, texture and edge quality rather than extra hues. Place the accent deliberately and preserve enough surrounding negative space for it to dominate without becoming oversized. Strong value structure, clean hierarchy and restrained art direction.","negative":"Multiple accent colours, weak contrast, random coloured reflections, excessive saturation, clutter, text, watermark.","kind":"composition","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Colour hierarchy","Minimal","Accent"]},
{"id":161,"title":"Sequential Motion Arc — Repeated Action","category":"composition","desc":"Show one action across a spatial arc with clear temporal progression.","prompt":"Create a single-frame motion study showing the same subject at three to five sequential positions along a clear arc of movement. Maintain identical subject identity, scale and proportions across repetitions; spacing communicates speed and direction. The earliest and latest positions remain readable, while intermediate states may use restrained motion transparency. Keep background fixed and avoid confusing overlap. Graphic editorial composition, precise rhythm and clean silhouette separation.","negative":"Different subjects, inconsistent scale, random duplication, impossible movement path, excessive blur, text, watermark.","kind":"composition","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Motion study","Repetition","Sequence"]},
{"id":162,"title":"Asymmetric Split Field — Two Visual Weights","category":"composition","desc":"Divide the frame into unequal zones with a deliberate relationship.","prompt":"Divide the canvas into two unequal visual fields using a strong vertical or horizontal boundary. Place one dominant image or form in the larger zone and a restrained counterweight in the smaller zone; align edges and margins to a coherent grid. Maintain a clear hierarchy across the boundary and use negative space to connect the fields. Limited palette, editorial precision and no decorative filler.","negative":"Equal halves without intent, unrelated imagery, misaligned margins, clutter, random gradients, pseudo-text, watermark.","kind":"composition","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Split field","Asymmetry","Editorial"]},
{"id":163,"title":"Central Void — Forms Orbiting Absence","category":"composition","desc":"Use a deliberate empty centre as the primary compositional device.","prompt":"Construct a composition in which multiple sculptural or graphic forms surround a sharply defined empty central void. Arrange the forms with consistent spatial logic and controlled variation in scale, leaving the centre completely unobstructed. Directional light and overlapping depth cues guide the eye around the void rather than into it. Strong silhouette design, disciplined negative space and a restrained material palette.","negative":"Objects entering centre, random scatter, weak empty-space definition, competing focal point, clutter, text, watermark.","kind":"composition","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Negative space","Void","Spatial rhythm"]},
{"id":164,"title":"Panoramic Sequence — Continuous Horizon","category":"composition","desc":"A wide horizontal frame with connected spatial zones.","prompt":"Create a panoramic composition divided into three connected spatial zones that read as one continuous environment. Maintain an unbroken horizon, consistent scale and coherent light direction across the full width. Each zone introduces a new visual event while preserving a clear path for the eye from left to right. Keep transitions seamless and reserve deliberate breathing space at both ends. Wide cinematic aspect, no panel borders or captions.","negative":"Discontinuous horizon, inconsistent perspective, unrelated scenes, hard panel seams, crowded edges, text, watermark.","kind":"composition","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Panorama","Continuity","Wide frame"]},
{"id":165,"title":"Infrared Film Grain — Luminance Texture","category":"filter-effects","desc":"Fine monochromatic grain with infrared-like tonal separation.","prompt":"Apply a restrained monochromatic infrared-film treatment with fine silver-grain structure. Deep foliage and dark fabrics retain texture, pale surfaces hold detail and skies separate into controlled mid-grey values. Grain density should increase subtly in midtones without forming clumps; preserve edge sharpness and original scene geometry. Emulate a carefully scanned medium-format negative with natural highlight roll-off.","negative":"Digital chroma noise, coarse grain clumps, posterisation, crushed shadows, artificial glow, changed objects, text, watermark.","kind":"effect","bg":"#101b38","art":"linear-gradient(130deg,#071b46,#6b35a8 52%,#f18a42)","glow":"#6655bd","model":["Midjourney","DALL·E","Flux"],"tags":["Film","Infrared","Grain"]},
{"id":166,"title":"Liquid Simulation — Viscous Pour","category":"3d-rendering","desc":"A continuous viscous fluid stream with coherent surface tension.","prompt":"Render a physically plausible viscous liquid pour from a small vessel into a shallow pool. The stream remains continuous, with believable necking, surface tension, impact crown and concentric ripples. Fluid thickness is syrup-like rather than watery; highlights follow the curved surface and settle into coherent reflections. Use a dark studio, high-speed product-photography framing and controlled backlight.","negative":"Broken stream, floating droplets without cause, rigid geometry, water-like thinness, chaotic splash, excessive bloom, text, watermark.","kind":"3d","bg":"#101a2b","art":"radial-gradient(circle at 70% 20%,#e98a39,transparent 30%),linear-gradient(130deg,#17263b,#080c16)","glow":"#d18a49","model":["Blender","Cinema 4D","Unreal Engine","Flux"],"tags":["Fluid simulation","Viscosity","Dynamics"]},
{"id":167,"title":"Procedural Stone — Vein Continuity","category":"3d-rendering","desc":"Layered mineral veining with believable geological structure.","prompt":"Create a physically based marble material with broad mineral strata and fine branching veins that continue coherently across adjacent faces. Vein density varies naturally and follows geological direction rather than repeating as a tile. Use a honed finish with subtle micro-roughness, restrained subsurface depth and soft grazing light. Present a clean cut block with two visible faces so pattern continuity can be judged.","negative":"Procedural tiling, random disconnected veins, excessive gloss, plastic stone, noisy speckles, impossible vein direction, text, watermark.","kind":"3d","bg":"#101a2b","art":"radial-gradient(circle at 70% 20%,#e98a39,transparent 30%),linear-gradient(130deg,#17263b,#080c16)","glow":"#d18a49","model":["Blender","Cinema 4D","Unreal Engine","Flux"],"tags":["Procedural material","Stone","Veining"]},
{"id":168,"title":"Glass Shader — Thin-Walled Vessel","category":"3d-rendering","desc":"Accurate thin-wall transmission, refraction and edge thickness.","prompt":"Render a simple thin-walled transparent glass vessel with physically plausible wall thickness, refractive distortion and Fresnel reflections. The background remains visible through the body with subtle displacement; the rim and base reveal thicker optical paths. Use a controlled studio environment with black and white cards, accurate roughness and clean caustic hints. Preserve a clear silhouette and neutral colour response.","negative":"Opaque body, invisible edges, thick solid-glass appearance, rainbow exaggeration, warped rim, cloudy surface, text, watermark.","kind":"3d","bg":"#101a2b","art":"radial-gradient(circle at 70% 20%,#e98a39,transparent 30%),linear-gradient(130deg,#17263b,#080c16)","glow":"#d18a49","model":["Blender","Cinema 4D","Unreal Engine","Flux"],"tags":["Glass shader","Refraction","Thin wall"]},
{"id":169,"title":"Photogrammetry Asset — Scan Fidelity","category":"3d-rendering","desc":"A scanned object retaining realistic micro-surface irregularity.","prompt":"Create a photorealistic 3D asset presentation that resembles a high-quality photogrammetry capture of a weathered stone artefact. Preserve small chips, pores, uneven albedo and subtle scan-level irregularities while maintaining a clean watertight silhouette. Use neutral diffuse lighting and a simple turntable-style three-quarter view. Surface detail must remain scale-consistent and grounded in the object's material history.","negative":"Procedural perfection, melted topology, excessive noise, invented ornament, glossy stone, floating asset, text, watermark.","kind":"3d","bg":"#101a2b","art":"radial-gradient(circle at 70% 20%,#e98a39,transparent 30%),linear-gradient(130deg,#17263b,#080c16)","glow":"#d18a49","model":["Blender","Cinema 4D","Unreal Engine","Flux"],"tags":["Photogrammetry","Asset","Scan detail"]},
{"id":170,"title":"Modernist Art Gallery — Skylit Hall","category":"environments","desc":"Quiet gallery architecture with controlled skylight and wall wash.","prompt":"Photograph a modernist art gallery hall with long white walls, a polished concrete floor and a linear skylight. Daylight falls in a broad soft band across the architecture, producing gradual shadow transitions and subtle floor reflections. Maintain precise verticals, believable ceiling height and generous negative space; artworks, if present, are minimal and secondary. Neutral architectural palette, wide-angle restraint and documentary realism.","negative":"Warped walls, excessive glare, crowded visitors, dramatic coloured lighting, invented signage, text, watermark.","kind":"environment","bg":"#182b39","art":"linear-gradient(130deg,#172d42,#7a593c 50%,#0d1725)","glow":"#7792a4","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Gallery","Modernist","Daylight"]},
{"id":171,"title":"Rainforest Canopy Walkway","category":"environments","desc":"Elevated timber path through layered humid forest vegetation.","prompt":"Create a realistic elevated walkway through a dense temperate rainforest canopy. The path and handrails recede with accurate perspective, while layered leaves and trunks establish foreground, middle distance and deep background. Humid air softens distant contrast; small droplets catch filtered daylight without creating fantasy sparkle. Materials show wet timber grain and weathered metal fixings. Observational landscape photography, believable ecology and human scale.","negative":"Tropical resort styling, impossible plant species, excessive mist, glowing particles, warped railing, text, watermark.","kind":"environment","bg":"#182b39","art":"linear-gradient(130deg,#172d42,#7a593c 50%,#0d1725)","glow":"#7792a4","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Forest","Architecture","Humidity"]},
{"id":172,"title":"Studio Beauty Dish — Sculpted Portrait","category":"photography","desc":"Focused portrait light with controlled cheekbone and jaw modelling.","prompt":"Create a professional head-and-shoulders portrait lit by a beauty dish positioned slightly above and close to camera axis. Preserve natural facial identity and skin texture; the light creates defined cheekbone modelling, a soft under-chin shadow and clean catchlights. Use subtle fill to retain shadow detail, a neutral background and a portrait lens perspective. Retouch only transient blemishes, not pores or facial structure.","negative":"Changed identity, wax skin, excessive sharpening, flat ring-light look, clipped forehead, altered eye shape, text, watermark.","kind":"photography","bg":"#242c34","art":"radial-gradient(circle at 80% 20%,#ff8a13,transparent 30%),linear-gradient(130deg,#252d36,#080b10)","glow":"#b18a62","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Portrait","Beauty dish","Studio lighting"]},
{"id":173,"title":"Backlit Translucent Object — Edge Transmission","category":"photography","desc":"Strong backlight reveals thin material edges and internal density.","prompt":"Photograph a translucent material object against a dark background using a strong diffused backlight. Thin edges transmit more light than dense central regions, revealing thickness and internal structure without turning the object uniformly luminous. Add a restrained side fill to retain surface texture and a narrow rim to define the silhouette. Accurate exposure, realistic transmission and macro product-photography precision.","negative":"Self-emission, opaque centre, clipped white edges, coloured glow, random reflections, flat front light, text, watermark.","kind":"photography","bg":"#242c34","art":"radial-gradient(circle at 80% 20%,#ff8a13,transparent 30%),linear-gradient(130deg,#252d36,#080b10)","glow":"#b18a62","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Backlight","Transmission","Product detail"]},
{"id":174,"title":"Telephoto Compression — Urban Layers","category":"photography","desc":"Compressed city depth with distinct atmospheric planes.","prompt":"Create a telephoto urban photograph from an elevated viewpoint, compressing multiple building layers into a dense but readable composition. Maintain straight architectural geometry and consistent scale relationships; atmospheric haze progressively softens distant structures. Late-afternoon side light picks out selected facades while shadowed streets remain detailed. Use a long focal length perspective, restrained contrast and a clear dominant mid-distance anchor.","negative":"Wide-angle distortion, inconsistent building scale, excessive haze, duplicated structures, fake miniature effect, text, watermark.","kind":"photography","bg":"#242c34","art":"radial-gradient(circle at 80% 20%,#ff8a13,transparent 30%),linear-gradient(130deg,#252d36,#080b10)","glow":"#b18a62","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Telephoto","Urban","Compression"]},
{"id":175,"title":"Minimal Brand Guidelines Sheet — Identity Rules","category":"graphic-design","desc":"A structured one-page system overview with consistent brand logic.","prompt":"Design a one-page visual identity guideline sheet showing a supplied logo, clear-space diagram, minimum-size examples, colour swatches and typography hierarchy. Maintain exact logo geometry and supplied brand colours; use a precise grid, aligned labels and consistent annotation style. All written labels must use exact supplied copy or remain blank. Neutral presentation background, crisp vector artwork and professional design-system clarity.","negative":"Altered logo, invented brand name, inconsistent swatches, pseudo-text, arbitrary spacing, decorative mockups, watermark.","kind":"graphic","bg":"#171b22","art":"linear-gradient(110deg,#171b22,#e55b10 70%,#11151c)","glow":"#e56a27","model":["Midjourney","DALL·E","Flux"],"tags":["Brand identity","Guidelines","System"]},
{"id":176,"title":"Geometric Icon Grid — Optical Consistency","category":"graphic-design","desc":"A family of icons sharing stroke, corner and proportion rules.","prompt":"Create a cohesive family of twelve simple geometric icons on a consistent grid. Use one stroke weight, shared corner radius, aligned optical centres and a limited set of primitive shapes. Each icon must remain distinct at small sizes while following the same construction logic. Present in a clean evenly spaced grid with a monochrome palette and no labels unless exact names are supplied.","negative":"Inconsistent stroke widths, arbitrary perspective, filled and outline styles mixed, uneven spacing, pseudo-text, watermark.","kind":"graphic","bg":"#171b22","art":"linear-gradient(110deg,#171b22,#e55b10 70%,#11151c)","glow":"#e56a27","model":["Midjourney","DALL·E","Flux"],"tags":["Iconography","Grid","Consistency"]},
{"id":177,"title":"Typographic Hierarchy Audit — Editorial Page","category":"graphic-design","desc":"A single page demonstrating clear levels and reading order.","prompt":"Create an editorial page layout with a clearly differentiated headline, standfirst, section heading, body column, pull quote and folio. Use a disciplined grid, readable measure, consistent baseline rhythm and intentional paragraph spacing. The reader's eye should move through a clear hierarchy without decorative clutter. Use exact supplied copy; if no copy is provided, use neutral blank text blocks rather than fabricated words.","negative":"Pseudo-language, inconsistent type sizes, narrow unreadable columns, random alignment, excessive ornaments, watermark.","kind":"graphic","bg":"#171b22","art":"linear-gradient(110deg,#171b22,#e55b10 70%,#11151c)","glow":"#e56a27","model":["Midjourney","DALL·E","Flux"],"tags":["Editorial","Hierarchy","Layout"]},
{"id":178,"title":"Monochrome Packaging Identity — Ink Economy","category":"graphic-design","desc":"A restrained one-ink packaging system with strong typographic form.","prompt":"Design a monochrome packaging identity using a single dark ink on natural uncoated stock. Build hierarchy through scale, weight, spacing and negative space rather than extra colours or decorative graphics. Show front and side panels in a flat presentation, with exact supplied brand marks preserved. Fine print details remain legible and aligned to a coherent grid; no invented copy.","negative":"Extra colours, gradients, fake logos, pseudo-text, glossy finish, inconsistent panel alignment, watermark.","kind":"graphic","bg":"#171b22","art":"linear-gradient(110deg,#171b22,#e55b10 70%,#11151c)","glow":"#e56a27","model":["Midjourney","DALL·E","Flux"],"tags":["Packaging","Monochrome","Typography"]},
{"id":179,"title":"Photo to Embossed Paper Relief — Depth Mapping","category":"transformations","desc":"Convert tonal information into shallow physical paper relief.","prompt":"Transform the supplied image into a monochrome embossed-paper relief. Translate major tonal boundaries into shallow raised and recessed contours while preserving the original subject silhouette and composition. Use one consistent paper stock, realistic fibre texture and a single raking light that reveals relief through soft shadows. Keep depth subtle and manufacturable; avoid sculptural exaggeration or added elements.","negative":"Full 3D sculpture, multiple materials, deep carved cuts, changed composition, painted gradients, text, watermark.","kind":"transform","bg":"#20182e","art":"linear-gradient(130deg,#17122c,#7447bc 50%,#12151e)","glow":"#9473d0","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Embossing","Paper","Relief"]},
{"id":180,"title":"Product Colourway Swap — Surface Mask Lock","category":"transformations","desc":"Change only selected product colours with material-aware masking.","prompt":"Change the supplied product to the specified colourway while preserving all geometry, labels, seams, texture and lighting. Apply the new colour only to the designated panels using accurate edge masks; retain material-specific highlights, shadows and roughness. Adjacent materials remain untouched and the original camera framing is locked. The result should resemble a genuine alternate production colourway.","negative":"Global tint, changed material finish, colour spill, altered logos, new seams, geometry edits, text, watermark.","kind":"transform","bg":"#20182e","art":"linear-gradient(130deg,#17122c,#7447bc 50%,#12151e)","glow":"#9473d0","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Colourway","Product edit","Masking"]},
{"id":181,"title":"Grid Interruption — One Deliberate Misalignment","category":"composition","desc":"A disciplined grid disrupted by a single controlled element.","prompt":"Build a precise modular grid composition with repeated aligned elements, consistent gutters and stable margins. Interrupt the system exactly once with one offset block or oversized form that breaks alignment while retaining overall balance. The interruption should become the focal event; all remaining elements obey the grid. Restrained palette, crisp edges and deliberate negative space.","negative":"Multiple misalignments, accidental tangencies, uneven gutters, random scatter, competing focal points, text, watermark.","kind":"composition","bg":"#18232d","art":"linear-gradient(135deg,#26394b,#8b6b50 52%,#121923)","glow":"#67839a","model":["Midjourney","DALL·E","Stable Diffusion","Flux"],"tags":["Grid","Disruption","Graphic design"]}
];
prompts.push(...(window.AI_PROMPT_EXPANSION||[]));
collections.forEach(c=>c.count=prompts.filter(p=>p.category===c.id).length);
const catalogueAudit={total:prompts.length,collections:collections.length,minimumPerCollection:Math.min(...collections.map(c=>c.count)),incomplete:collections.filter(c=>c.count<50).map(c=>({id:c.id,name:c.name,count:c.count}))};
window.AI_PROMPT_LIBRARY_AUDIT=catalogueAudit;
if(catalogueAudit.incomplete.length)console.error("AI Prompt Library catalogue integrity check failed",catalogueAudit);
const $=s=>document.querySelector(s);
const collectionName=id=>collections.find(c=>c.id===id)?.name||id;
const promptGrid=$("#prompt-grid");
let activePrompt=null,showingAll=document.body.dataset.page==="explore";
function collectionCard(c){return `<a class="collection-card" data-tone="${c.tone}" href="#archive" data-category="${c.id}" style="--card-bg:${c.bg}"><span class="collection-icon">${c.icon}</span><span class="collection-meta"><strong>${c.name}</strong><small>${c.count} prompts · ${c.count>=50?"complete":"catalogue incomplete"}</small></span><span class="collection-arrow">→</span></a>`}
function thumb(p){return `<div class="prompt-thumb" data-kind="${p.kind}" style="--thumb-bg:${p.bg};--thumb-art:${p.art};--thumb-glow:${p.glow}"><div class="thumb-art"></div><button class="bookmark" aria-label="Save ${p.title}" title="Save prompt">♧</button></div>`}
function promptCard(p){return `<article class="prompt-card" data-id="${p.id}" tabindex="0" role="button" aria-label="Open ${p.title}">${thumb(p)}<div class="prompt-info"><h3>${p.title}</h3><div class="prompt-meta"><span class="pill">${collectionName(p.category)}</span><small>${difficulty(p)} ↗</small></div></div></article>`}
function difficulty(p){const t=(p.tags||[]).join(" ").toLowerCase();return p.difficulty||((p.prompt.length>520||/technical|optical|physics|procedural|macro/.test(t))?"Professional":p.prompt.length>300?"Advanced":"Foundation");}
function masterPrompt(p){return `UNIVERSAL ART DNA — MASTER PROMPT
Transform the following creative brief into a fully art-directed, visually coherent image while preserving its original subject, intent and essential technical requirements.

CORE CREATIVE BRIEF:
${p.prompt}

ART DIRECTION:
Establish a clear visual concept and focal hierarchy. Refine the composition, spatial relationships, framing, camera perspective and negative space. Develop a deliberate colour strategy, tonal structure and lighting design. Give every material, surface and object physically or stylistically coherent behaviour. Introduce depth, atmosphere and controlled detail without clutter. Make every visual decision support the original concept.

CRAFT & FIDELITY:
Prioritise accurate subject construction, intentional shape language, convincing textures, coherent shadows and reflections, clean edge behaviour and consistent perspective. Balance micro-detail with overall readability. Deliver a distinctive, polished result with professional visual judgement.

PRESERVATION RULES:
Do not change the core subject, remove essential details, invent unrelated objects, distort required geometry or compromise the original output purpose. Do not add decorative effects unless they strengthen the brief. Retain all explicit constraints.

OUTPUT INTENT:
${p.desc}
Create a resolved, high-quality image with strong visual identity and disciplined execution.`;}
function universalTemplatePrompt(p){
return `UNIVERSAL TEMPLATE PROMPT — VARIABLE-BASED GENERATION
Use this reusable structure to generate a new visual from a defined creative brief. Replace every bracketed field with a precise value; remove any field that is not relevant. Do not leave unresolved placeholders in the final generation.

[PRIMARY SUBJECT]: ${p.title.split(" — ")[0]} / [INSERT SUBJECT OR OBJECT]
[SUBJECT DESCRIPTION & DISTINCTIVE FEATURES]: [DEFINE FORM, IDENTITY, PROPORTIONS, DETAILS AND REQUIRED CHARACTERISTICS]
[VISUAL STYLE / ART MOVEMENT]: [INSERT STYLE, REFERENCE LANGUAGE OR ART DIRECTION]
[MEDIUM / MATERIAL / SURFACE]: [INSERT MATERIALS, FINISHES, TEXTURES OR RENDERING MEDIUM]
[ENVIRONMENT / BACKGROUND]: [INSERT SETTING, CONTEXT AND ATMOSPHERIC CONDITIONS]
[COMPOSITION & CAMERA]: [INSERT VIEWPOINT, LENS OR PERSPECTIVE, FRAMING, SCALE, HIERARCHY AND NEGATIVE SPACE]
[LIGHTING]: [INSERT LIGHT SOURCE, DIRECTION, QUALITY, CONTRAST AND COLOUR TEMPERATURE]
[COLOUR SYSTEM]: [INSERT PALETTE, TONAL RANGE AND COLOUR RELATIONSHIPS]
[DETAIL & FIDELITY]: [INSERT REQUIRED MICRO-DETAIL, REALISM LEVEL, EDGE QUALITY AND FINISH]
[OUTPUT FORMAT / PURPOSE]: [INSERT ASPECT RATIO, RESOLUTION, PRESENTATION OR PRODUCTION USE]

GENERATION BRIEF:
Create [PRIMARY SUBJECT] as [SUBJECT DESCRIPTION & DISTINCTIVE FEATURES]. Interpret the brief through [VISUAL STYLE / ART MOVEMENT], using [MEDIUM / MATERIAL / SURFACE]. Place the subject within [ENVIRONMENT / BACKGROUND]. Construct the image using [COMPOSITION & CAMERA]. Illuminate it with [LIGHTING] and apply [COLOUR SYSTEM]. Prioritise [DETAIL & FIDELITY]. The final output must satisfy [OUTPUT FORMAT / PURPOSE].

SUBJECT-SPECIFIC CREATIVE DIRECTION:
Use the following specialist reference as the starting point, adapting it to the completed variables rather than copying it mechanically:
${p.prompt}

QUALITY CONTROL:
Maintain internal consistency between subject, scale, materials, lighting, perspective and visual style. Establish one clear focal hierarchy. Avoid generic filler, contradictory instructions, accidental clutter, malformed structure, weak material response and details that do not support the brief.

[NEGATIVE PROMPT / EXCLUSIONS]: ${p.negative}
`;
}
function universalTransformationPrompt(p){
return `UNIVERSAL TRANSFORMATION PROMPT

Transform the supplied image by applying the visual treatment of ${p.title}. Use the existing image as the source and preserve its subject.

Apply this complete visual treatment to the source image:
${p.prompt}

Interpret the treatment above as the target style, material, surface, effect or rendering direction. Transfer its relevant visual characteristics onto the existing subject; do not recreate or substitute the example subject described in the treatment prompt.

Preserve the source subject's identity, defining features, shape, proportions, pose, expression, objects and composition. Modify only its visual treatment as needed to achieve the result. Keep all unrelated details unchanged.

Avoid: ${p.negative}
`;
}
function renderCollections(){$("#collection-grid").innerHTML=collections.map(collectionCard).join("");$("#category-filter").innerHTML='<option value="all">All collections</option>'+collections.map(c=>`<option value="${c.id}">${c.name} (${c.count})</option>`).join("");document.querySelectorAll(".collection-card").forEach(el=>el.addEventListener("click",()=>{$("#category-filter").value=el.dataset.category;showingAll=true;filterPrompts();}));}
function filterPrompts(){const q=$("#archive-search").value.trim().toLowerCase();const cat=$("#category-filter").value;const model=$("#model-filter").value;const visual=$("#visual-filter")?.value||"all";const sort=$("#sort-filter").value;let list=prompts.filter(p=>(cat==="all"||p.category===cat)&&(model==="all"||p.model.includes(model))&&(visual==="all"||(p.tags||[]).some(t=>t.toLowerCase().includes(visual)))&&[p.title,p.desc,p.prompt,p.tags.join(" "),collectionName(p.category)].join(" ").toLowerCase().includes(q));if(!showingAll)list=list.slice(0,5);if(sort==="az")list.sort((a,b)=>a.title.localeCompare(b.title));promptGrid.innerHTML=list.map(promptCard).join("");$("#empty-state").hidden=list.length>0;$("#result-count").textContent=`Showing ${list.length} of ${prompts.length} prompts across ${collections.length} collections`;document.querySelectorAll(".prompt-card").forEach(card=>{card.addEventListener("click",e=>{if(e.target.closest(".bookmark"))return;openPrompt(Number(card.dataset.id));});card.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();openPrompt(Number(card.dataset.id));}});});document.querySelectorAll(".bookmark").forEach(btn=>btn.addEventListener("click",e=>{e.stopPropagation();btn.classList.toggle("saved");btn.textContent=btn.classList.contains("saved")?"♥":"♧";showToast(btn.classList.contains("saved")?"Saved to this session":"Removed from saved");}));}
function openPrompt(id){const p=prompts.find(x=>x.id===id);if(!p)return;activePrompt=p;$("#dialog-content").innerHTML=`<p class="detail-category">${collectionName(p.category)} / PROMPT ${String(p.id).padStart(3,"0")}</p><h2 class="detail-title">${p.title}</h2><p class="detail-desc">${p.desc}</p><div class="detail-tags">${p.model.map(m=>`<span>${m}</span>`).join("")}${p.tags.map(t=>`<span>${t}</span>`).join("")}<span class="difficulty-tag">${difficulty(p)}</span></div><div class="prompt-mode-tabs"><button class="mode-tab active" data-mode="standard">Standard Prompt</button><button class="mode-tab" data-mode="template">Universal Template</button><button class="mode-tab" data-mode="transformation">Universal Transformation</button><button class="mode-tab" data-mode="master">MASTER PROMPT · ART DNA</button></div><p class="prompt-label" id="active-prompt-label">STANDARD PROMPT / COPY-READY</p><div class="prompt-code" id="detail-prompt"></div><div class="detail-actions"><button class="button button-orange" id="copy-prompt">▢ Copy selected prompt</button><button class="button button-outline" id="copy-negative">▢ Copy negative prompt</button></div><div class="detail-extra"><details open><summary>Prompt breakdown</summary><p>This prompt is structured around the subject, material or effect, physical characteristics, lighting, composition and output quality. Keep these components intact when adapting the prompt.</p></details><details><summary>Variation ideas</summary><p>Try changing the lighting direction, camera distance, colour temperature or environment while keeping the core concept consistent.</p></details></div>`;let mode="standard";const chosen=()=>mode==="master"?masterPrompt(p):mode==="template"?universalTemplatePrompt(p):mode==="transformation"?universalTransformationPrompt(p):p.prompt;$("#detail-prompt").textContent=chosen();document.querySelectorAll(".mode-tab").forEach(b=>b.addEventListener("click",()=>{mode=b.dataset.mode;document.querySelectorAll(".mode-tab").forEach(x=>x.classList.toggle("active",x===b));$("#active-prompt-label").textContent=mode==="master"?"MASTER PROMPT / UNIVERSAL ART DNA":mode==="template"?"UNIVERSAL TEMPLATE / VARIABLE-BASED GENERATION":mode==="transformation"?"UNIVERSAL TRANSFORMATION / SOURCE-BASED EDITING":"STANDARD PROMPT / COPY-READY";$("#detail-prompt").textContent=chosen();}));$("#copy-prompt").addEventListener("click",()=>copyText(chosen()));$("#copy-negative").addEventListener("click",()=>copyText(p.negative));$("#prompt-dialog").showModal();}
async function copyText(text){try{await navigator.clipboard.writeText(text);showToast("Prompt copied to clipboard");}catch{const area=document.createElement("textarea");area.value=text;document.body.append(area);area.select();document.execCommand("copy");area.remove();showToast("Prompt copied");}}
let toastTimer;function showToast(msg){const t=$("#toast");t.textContent=msg;t.classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove("show"),2200);}
if($("#collection-grid"))renderCollections();if($("#prompt-grid"))filterPrompts();
const promptOfDay=prompts[new Date().getDate()%prompts.length];if(promptOfDay){const pod=$("#prompt-of-day");if(pod){pod.innerHTML=`<span class="eyebrow">PROMPT OF THE DAY</span><strong>${promptOfDay.title}</strong><p>${promptOfDay.desc}</p><button class="button button-orange" id="open-pod">Explore prompt →</button>`;$("#open-pod").addEventListener("click",()=>openPrompt(promptOfDay.id));}}
const builder=$("#dna-builder");if(builder){
 const groups=[
  {id:"materials",label:"Materials",categories:["materials"],description:"Physical substances, finishes and material behaviour."},
  {id:"styles",label:"Visual styles",categories:["graphic-design","anime-manga","surrealism","animation-toy-worlds"],description:"Visual languages, art movements and stylistic treatments."},
  {id:"effects",label:"Effects & optics",categories:["filter-effects","typography-effects","motion"],description:"Optical, photographic, digital and surface effects."},
  {id:"textures",label:"Textures & surfaces",categories:["materials"],description:"Surface qualities, grain, relief and tactile detail."},
  {id:"lighting",label:"Lighting",categories:["photography"],description:"Lighting setups, atmosphere and illumination behaviour."},
  {id:"composition",label:"Composition & framing",categories:["composition"],description:"Spatial organisation, visual hierarchy and framing."},
  {id:"rendering",label:"Rendering & image craft",categories:["3d-rendering"],description:"Rendering methods, image fidelity and production finish."},
  {id:"transformation",label:"Transformations",categories:["transformations"],description:"Transfer a visual treatment onto an existing source image."}
 ];
 const selected=new Set();
 const byId=new Map(prompts.map(p=>[String(p.id),p]));
 const universal=groups.flatMap(g=>g.categories).reduce((s,c)=>s.add(c),new Set());
 const uniquePrompts=[...new Map(prompts.filter(p=>universal.has(p.category)).map(p=>[String(p.id),p])).values()];
 const groupItems=(g)=>uniquePrompts.filter(p=>g.categories.includes(p.category)).sort((a,b)=>a.title.localeCompare(b.title));
 const esc=(v)=>String(v).replace(/[&<>"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[ch]));
 const renderGroups=()=>{
  $("#builder-modules").innerHTML=groups.map(g=>{
   const items=groupItems(g);
   return '<section class="builder-module"><div class="builder-module-heading"><div><h3>'+g.label+'</h3><p>'+g.description+'</p></div><span>'+items.length+' elements</span></div><div class="builder-module-grid">'+items.map(p=>'<label class="builder-option"><input type="checkbox" data-prompt-id="'+p.id+'" '+(selected.has(String(p.id))?'checked':'')+'><span>'+esc(p.title)+'</span></label>').join("")+'</div></section>';
  }).join("");
  $("#builder-modules").querySelectorAll('input[data-prompt-id]').forEach(input=>input.addEventListener("change",()=>{const id=input.dataset.promptId;if(input.checked)selected.add(id);else selected.delete(id);compose();}));
 };
 const compose=()=>{
  const chosen=[...selected].map(id=>byId.get(id)).filter(Boolean);
  const type=$("#builder-type").value;
  const style=$("#builder-style").value.trim();
  const light=$("#builder-light").value.trim();
  const frame=$("#builder-frame").value.trim();
  const source=$("#builder-source").value.trim();
  const sections=chosen.map(p=>p.title+"\n"+p.prompt).join("\n\n");
  const treatment=type==="transformation"?"Apply the selected visual modules to the supplied source image. Preserve the source subject, identity, defining features, proportions, pose and essential composition; change only the requested visual treatment.":type==="art-dna"?"Create a cohesive ART DNA system from the selected visual modules. Resolve conflicts intelligently, establish a clear hierarchy and apply consistent visual logic throughout.":"Create a coherent image using the selected visual modules as independent, compatible art-direction instructions.";
  const output=["PROMPT DNA — MODULAR VISUAL SYSTEM",treatment,source?"SOURCE / SUBJECT:\n"+source:"",sections?"SELECTED VISUAL MODULES:\n"+sections:"SELECT AT LEAST ONE VISUAL MODULE TO BEGIN.", "ADDITIONAL ART DIRECTION:\nVisual style: "+(style||"No additional style specified")+".\nLighting: "+(light||"No additional lighting specified")+".\nComposition: "+(frame||"No additional composition specified")+".","INTEGRATION RULES:\nTreat each selected module as an independent instruction. Combine them without allowing one module to replace or contradict the others. Preserve material accuracy, visual coherence, controlled detail, clear focal hierarchy and professional image quality. Avoid unrelated objects, arbitrary decoration, visual clutter, inconsistent lighting and conflicting surface behaviour."].filter(Boolean).join("\n\n");
  $("#builder-output").textContent=output;
  $("#builder-selection-count").textContent=chosen.length+" selected";
 };
 $("#builder-type").addEventListener("change",compose);
 ["builder-style","builder-light","builder-frame","builder-source"].forEach(id=>$("#"+id).addEventListener(id==="builder-source"?"input":"change",compose));
 $("#builder-clear").addEventListener("click",()=>{selected.clear();renderGroups();compose();});
 $("#copy-builder").addEventListener("click",()=>copyText($("#builder-output").textContent));
 renderGroups();compose();
}
